    const kat = _figSkalDoman({ ...figurIn, lager: figurIn.lager.map(l => ({ ...l, data: l.data.filter(d => d) })) }, 'y');
    if (kat.length <= RF_RADPANEL_MAX) return null;
    const delar = [];
