// ====================================================================
// 10-diagramtema.js — Delat diagram-tema (visualiserings-Steg 1)
//
// ENDA KÄLLA för diagrammens färger och typografi: paletten (kön, status, serier, färgskalor) och diagrammens
// teckensnitt. Diagramkärnan (10-diagramritare.js, ADR-39) och vyernas figurer läser härifrån — ingen vy har en
// egen hexkod.
// ====================================================================

// Kanonisk färgpalett. All könsfärgning och alla semantiska färger härleds
// härifrån (se `const colors` i 12-tillstand.js, som speglar PALETTE.kon).
const PALETTE = {
    // Kön — genomgående i hela verktyget. Plommon för kvinnor och olivgrönt för män (beslut 2026-10-17):
    // inte rosa och blått, som kopplar färgen till en stereotyp. Båda har minst 4,5:1 mot vit yta (7,1 och
    // 4,6), skiljer sig mer än det tidigare paret vid simulerad protanopi och deuteranopi, och ligger tydligt ifrån
    // statusfärgerna (granska, ok, varning) och seriefärgerna. Kön står alltid också med ord i legenden.
    // Prövas i tests/farger.test.js.
    kon: { kvinna: '#833a8f', man: '#5f7f16' },
    // Semantiska statusfärger (avvikelse/varning/ok m.m.).
    semantic: {
        policy:   '#d24723',
        // Statusfärgerna har minst 3:1 i kontrast mot vit bakgrund (WCAG 1.4.11) och skiljer sig i ljushet och
        // ton också för den som har svårt att skilja rött från grönt: mörkt rött, mellanljus bärnsten, blågrönt.
        kritisk:  FARG.kritisk,
        varning:  '#d97706',
        ok:       FARG.ok,
        neutral:  FARG.svag,
        referens: FARG.svag,
        linje:    FARG.dampad,   // mörk neutral linje (P90, felstaplar)
        trend:    '#1c5cab',   // trendlinje över punkter i seriens första färg
        spann:    '#d5dae3',   // referensens spann (P10–P90) bakom organisationens
        mork:     FARG.text    // markörer som ska synas mot både röd och grön stapel
    },
    // Kvalitativ serie-palett för diagram med många kategorier (t.ex. AID).
    // De åtta första i den här ordningen klarar kontrollen för färgblindhet mellan grannar. De fyra sista är mörkare
    // steg av de fyra första, för de få vyer som har fler än åtta serier (Utforska tillåter tolv segment).
    serie: ['#2a78d6', '#eb6834', '#1baf7a', '#eda100', '#e87ba4', '#008300', '#4a3aa7', '#e34948',
            '#184f95', '#a84418', '#0f7a55', '#8a6a00'],
    // Divergerande skala för heatmaps, centrerad på neutral mitt.
    // Låg (rött) = kvinnors median klart under männens; hög (blått) = över.
    // Två kulörer och en neutral mitt: varmt åt ena hållet, kallt åt det andra (fler kulörer läses som regnbåge).
    divergerande: [
        [0.0, '#a5371a'], [0.25, '#e59a7b'], [0.5, '#eeeeec'],
        [0.75, '#86b6ef'], [1.0, '#1c5cab']
    ],
    // Sekventiell (enkelriktad) skala: ljus → varm/röd. Används där måttet bara
    // går åt ett håll, t.ex. § 3:10-gapet (jämförelseyrket tjänar mer → rödare).
    // En kulör från ljus till mörk.
    sekventiell: [[0.0, '#fbe3d6'], [0.5, '#e8703c'], [1.0, '#8a2f10']],
    // Neutral sekventiell skala för mått där högt varken är bra eller dåligt (lön, antal).
    sekventiellNeutral: [[0, '#dce9fb'], [0.5, '#5598e7'], [1, '#0d366b']],
    // Prioriteringsmatrisens statusar (samma nyanser som statusbrickorna i fliken).
    // Prioriteringens statusar. «Börja här» och «Värt att granska» är lila — samma färg som statusen «Värt att granska»
    // i Lika arbetes yrkesgruppstabell (lila överallt, inte rött). Lila säger «titta
    // här först» utan att påstå att något är fel; rött är förbehållet avvikelser över 5 %.
    prio: { akut: FARG.granska, atgard: FARG.granskaLjus, bevaka: '#d97706', ok: FARG.ok, analysera: FARG.info }
};

// Gemensamt teckensnitt/typografi för diagram (matchar appens sans-stack).
const CHART_FONT = {
    family: 'system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif',
    size: 12,
    color: '#1f2430',
    dampad: '#5b6472'      // axlarnas siffror och rubriker: ett steg lugnare än diagrammets egna etiketter
};
// SPDX-License-Identifier: MIT
// Copyright 2026 Felix Jansson
// ====================================================================
// 11-diagramexport.js — Exportmeny på alla diagram
//
// Varje diagram ritas av diagramkärnan (ritaFigur, ADR-39), som lägger till menyn — så ALLA diagram, även
// framtida, får samma meny utan att någon kommer ihåg att lägga till en knapp.
//
// Kontrakt för vyer:
//   markeraUtanExport(el, skal)     — behållaren (och allt i den) lämnar inte verktyget; skälet ur EXPORT_SKAL.
//   exportBeskrivning (ritaFigur)   — blir rad 2 i diagramdatan och står i bildens fotrad (Utforskas urval).
//   exportMedSma (ritaFigur)        — funktion som svarar om små grupper ska följa med (Utforskas kryssruta).
//   figur.individer                 — figuren har en punkt per person: diagramdatan får raden om att filen
//                                     innehåller en rad per person och ska hanteras som personuppgifter (kIndividRad).
//
// Diagrammet exporteras ur sin figur (gd._figur) genom _rfExportFigur: bilden ritas utan små grupper och
// diagramdatan filtreras med utanSmaGrupper, om inte vyn har begärt annat. Finns inget att exportera —
// behållaren har ingen figur (felläge, rensad) eller alla punkter hör till små grupper — lämnar ingenting
// verktyget: menyn säger det i sin felrad.
//
// Underlaget (_chartExportUnderlag — där vyn tillfrågas om små grupper) bestäms EN gång per export, i
// chartExportRun, och lämnas vidare till innehållet och stämpeln: de kan då aldrig komma ur olika svar.
// Rensas eller ritas diagrammet om medan bilden görs laddas ingenting ner.
// ====================================================================

// ---- När ett diagram inte får lämna verktyget ----
// Regeln står här och bara här. Ett diagram får inte lämna verktyget — ingen exportmeny, ingen bild till ZIP-filen,
// rapportunderlaget eller utskriften (diagramTillBild), ingen diagramdata — när det står i en behållare som vyn har
// märkt med markeraUtanExport. Skälen är få och uppräknade; ett diagram utan registrerat skäl kan inte märkas, så
// det syns i koden varför varje spärr finns, och användaren ser det i behållarens verktygstips.
const EXPORT_SKAL = {
    // Personer att granska (ADR-23): panelen visar enskilda personer med filens radnummer. Diagrammet namnger ingen
    // och bär ingen lön, men hör till panelen, och inget ur den lämnar verktyget.
    individer: 'hör till Personer att granska, som visar enskilda personer (ADR-23)',
    // Översiktens kopior av Struktur & rapportmåtts diagram: samma bild exporteras från sin egen flik, en gång.
    kopia: 'är en kopia av ett diagram i Struktur & rapportmått och exporteras därifrån'
};
/** Märker en behållare: inget diagram i den lämnar verktyget. `skal` måste vara en nyckel i EXPORT_SKAL. */
function markeraUtanExport(el, skal) {
    if (!el) return;
    if (!Object.prototype.hasOwnProperty.call(EXPORT_SKAL, skal)) throw new Error(`markeraUtanExport: okänt skäl "${skal}"`);
    el.setAttribute('data-no-export', skal);
    el.title = `Lämnar inte verktyget: ${EXPORT_SKAL[skal]}.`;
}
/** Skälet till att diagrammet i behållaren inte får lämna verktyget, eller null när det får det. */
function exportSkal(behallare) {
    const m = behallare && behallare.closest ? behallare.closest('[data-no-export]') : null;
    if (!m) return null;
    // En märkning utan registrerat skäl spärrar ändå: hellre ett diagram för lite i en export än ett för mycket.
    return EXPORT_SKAL[m.getAttribute('data-no-export')] || 'är märkt utan export';
}
/** Får diagrammet i behållaren lämna verktyget (meny, bild, diagramdata, ZIP, utskrift)? */
function exportTillaten(behallare) { return exportSkal(behallare) == null; }

const CHART_EXPORT_STORLEKAR = {
    'png-presentation': [1920, 1080],
    'png-dokument':     [1600, 900],
    svg:                [1600, 900]
};
let _chartExportSeq = 0;

function _chartExportEl(graphDiv) {
    return typeof graphDiv === 'string' ? document.getElementById(graphDiv) : graphDiv;
}
function _chartExportSlug(s) {
    return String(s || '').normalize('NFC').replace(/[^\p{L}\p{N}]+/gu, '-').replace(/^-+|-+$/g, '').slice(0, 60);
}

/** Diagrammets rubrik: närmaste h2/h3 i samma kort, annars elementets id. */
function chartExportTitle(gd) {
    const kort = gd.closest ? gd.closest('.card') : null;
    const h = kort ? kort.querySelector('h2, h3') : null;
    const t = h ? h.textContent.replace(/\s+/g, ' ').trim() : '';
    return t || gd.id || 'Diagram';
}

/** <DEMO_>Flik_Rubrik_ÅÅÅÅ-MM-DD.ext */
function chartExportFilename(gd, ext, datum = new Date()) {
    const panel = gd.closest ? gd.closest('.view-panel') : null;
    const flik = panel && panel.id ? panel.id.replace(/^view-/, '') : 'diagram';
    const Flik = flik.charAt(0).toUpperCase() + flik.slice(1);
    const pad = n => String(n).padStart(2, '0');
    const dag = `${datum.getFullYear()}-${pad(datum.getMonth() + 1)}-${pad(datum.getDate())}`;
    const titel = _chartExportSlug(chartExportTitle(gd)) || 'Diagram';
    return `${state.isDemo ? 'DEMO_' : ''}${_chartExportSlug(Flik)}_${titel}_${dag}.${ext}`;
}

// Svensk Excel läser "89.73" som text eller datum ("12.5" blir 12 maj). Decimaltal
// avrundas därför till två decimaler och skrivs med decimalkomma; heltal lämnas.
function _chartExportCell(v) {
    if (typeof v !== 'number' || Number.isInteger(v) || !isFinite(v)) return v;
    return String(Math.round(v * 100) / 100).replace('.', ',');
}

// Har ritaFigur ritat i behållaren? Ja om den bär en figur, eller har burit en (felläge eller rensad: menyn står kvar
// utan figur, och svarar då att det inte finns något att exportera).
function _chartExportKarna(gd) {
    return !!gd && (!!gd._figur || _rfHarRitat(gd));
}

/** Behållaren som gäller nu: en omritning i exportgrinden kan ha ersatt den med en ny med samma id. */
function _chartExportAktuell(gd) { return gd && gd.isConnected === false && gd.id ? (document.getElementById(gd.id) || gd) : gd; }

/** Det som får exporteras ur ett diagram ritat med diagramkärnan, eller null när inget finns att exportera.
 *  Går alltid genom exportläget (ADR-51): figuren läses med den inställda tröskeln. Bilden görs asynkront av dem som
 *  anropar (chartExportRun, diagramTillBild), som själva står i exportläget tills bilden är klar. */
function _chartExportUnderlag(...a) { return medExportLage(() => _chartExportUnderlagExport.apply(null, /** @type {any} */ (a))); }
function _chartExportUnderlagExport(gd) {
    // Ett diagram som inte får lämna verktyget (markeraUtanExport) har inget att exportera, vilken väg som än frågar.
    if (!exportTillaten(gd)) return null;
    // Exportgrinden (23-exportgrind.js): diagrammets flik ska vara ritad med det som gäller nu. Ett diagram som en
    // omritning har ersatt (det gamla elementet sitter inte kvar i sidan) har inget att exportera.
    if (typeof exportSakra === 'function' && !exportSakra(gd)) {
        // Omritningen kan ha ersatt behållaren: då gäller den nya med samma id.
        const ny = gd.isConnected === false && gd.id ? document.getElementById(gd.id) : null;
        if (!ny || ny === gd || !exportSakra(ny)) return null;
        gd = ny;
    }
    const ut = _rfExportFigur(gd);
    return ut && !ut.tom ? ut : null;
}

/** Diagramdata med en spårbarhetsrad överst (ADR-13). Diagram ritade med diagramkärnan (ADR-39) går genom
 *  figurTillTabell — alla serier, också de som dolts via förklaringen; en låda blir statistik per kategori.
 *  Finns inget att exportera: inga rader alls.
 *  `underlag` är exportens underlag när anroparen redan har bestämt det (chartExportRun); utelämnat bestäms
 *  det här. Stämpeln får samma svar om små grupper som innehållet. */
function chartExportRows(gd, underlag) {
    const ut = underlag === undefined ? _chartExportUnderlag(gd) : underlag;
    if (!ut) return [];
    gd = _chartExportAktuell(gd);
    const medSma = ut.visaSma;
    const rader = _figTillTabell(medSma ? ut.figur : _figUtanSma(ut.figur)).map(r => r.map(_chartExportCell));
    const beskrivning = typeof gd._exportBeskrivning === 'string' ? gd._exportBeskrivning : '';
    // En figur med en punkt per person (figurens `individer`) ger en rad per person: filen säger det på rad 2.
    const individer = ut.figur && ut.figur.individer === true;
    return [[`${chartExportTitle(gd)} — Lönekartläggning ${APP_VERSION}. ${kStampelFor(_kUndantagFor(gd, medSma))}`],
            ...(individer ? [[kIndividRad()]] : []),
            ...(beskrivning ? [[`Urval: ${beskrivning}`]] : []), ...rader];
}

/** Rubrik och fotrad till en exporterad bild av ett kärnritat diagram: bilden ska säga själv vad den visar när den
 *  klistras in i ett dokument. Foten: verktyget och dagens datum, och urvalet om vyn har angett ett. */
function _chartExportRubrikFot(gd, datum = new Date()) {
    const p = n => String(n).padStart(2, '0');
    const dag = `${datum.getFullYear()}-${p(datum.getMonth() + 1)}-${p(datum.getDate())}`;
    const urval = typeof gd._exportBeskrivning === 'string' && gd._exportBeskrivning ? ` · Urval: ${gd._exportBeskrivning}` : '';
    // Ett zoomat diagram exporteras som det visas: fotraden säger att bilden är ett utsnitt.
    // Vyns anteckning (val.exportAnteckning) står först i fotraden: en mening om det bilden visar, räknad av vyn
    // ur värden som får visas.
    const v = gd._figurVal && typeof gd._figurVal.exportAnteckning === 'string' ? gd._figurVal.exportAnteckning.trim() : '';
    return { rubrik: chartExportTitle(gd), fot: `${v ? v + ' · ' : ''}Lönekartläggning ${dag}${urval}${gd._rfZoom ? ' · Utsnitt av diagrammet' : ''}` };
}

/** Bär elementet ett ritat diagram med något att visa? */
function diagramRitat(el) {
    return !!el && !!_chartExportUnderlag(el);
}

/** Ett ritat diagram som PNG (data-URL) — den enda vägen till en diagrambild för rapportunderlag, ZIP, utskrift
 *  och prioriteringsmatrisen (ADR-39): originalfiguren utan små grupper (om inte vyn sagt annat) och med de serier
 *  användaren dolt. `utanRubrik`: bilden får ingen rubrik och fotrad (utskriften sätter egna rubriker). */
// Går alltid genom exportläget (ADR-51): djupräknaren håller skärmen i exportläget tills den sista pågående exporten är klar.
function diagramTillBild(...a) { return medExportLage(() => _diagramTillBildExport.apply(null, /** @type {any} */ (a))); }
async function _diagramTillBildExport(el, val) {
    const { bredd, hojd, utanRubrik = false } = val || {};
    const skal = exportSkal(el);
    if (skal) throw new Error(`Diagrammet lämnar inte verktyget: det ${skal}.`);
    const ut = _chartExportUnderlag(el);
    el = _chartExportAktuell(el);
    if (!ut) throw new Error('Det finns inget att exportera i diagrammet.');
    const url = await figurTillBild(ut.bild || ut.figur, 'png', bredd, hojd, { visaSma: ut.visaSma, dolda: ut.dolda, ...(utanRubrik ? {} : _chartExportRubrikFot(el)) });
    if (el._figur !== ut.figur) throw new Error('Diagrammet rensades innan exporten blev klar.');
    return url;
}

// Går alltid genom exportläget (ADR-51): djupräknaren håller skärmen i exportläget tills den sista pågående exporten är klar.
function _chartExportImage(...a) { return medExportLage(() => __chartExportImageExport.apply(null, /** @type {any} */ (a))); }
async function __chartExportImageExport(gd, val, underlag) {
    const [width, height] = CHART_EXPORT_STORLEKAR[val];
    const format = val === 'svg' ? 'svg' : 'png';
    // Originalfiguren med visaSma enligt vyn och de serier användaren dolt: samma bild som på skärmen,
    // utan små grupper. Meningen om sänkt tröskel lägger figurTillSvg dit.
    const ut = underlag === undefined ? _chartExportUnderlag(gd) : underlag;
    gd = _chartExportAktuell(gd);
    if (!ut) throw new Error('Det finns inget att exportera i diagrammet.');
    const url = await figurTillBild(ut.bild || ut.figur, format, width, height, { visaSma: ut.visaSma, dolda: ut.dolda, ..._chartExportRubrikFot(gd) });
    // Bilden görs asynkront. Har diagrammet under tiden rensats (Rensa all data) eller fått en annan figur
    // lämnar bilden av den gamla inte verktyget.
    if (gd._figur !== ut.figur) throw new Error('Diagrammet rensades innan exporten blev klar.');
    const a = document.createElement('a');
    a.href = url;
    a.download = chartExportFilename(gd, format);
    a.style.display = 'none';
    document.body.appendChild(a);
    a.click();
    a.remove();
    if (typeof _showExportSensitivityToast === 'function') _showExportSensitivityToast();
}

// Går alltid genom exportläget (ADR-51): djupräknaren håller skärmen i exportläget tills den sista pågående exporten är klar.
function chartExportRun(...a) { return medExportLage(() => _chartExportRunExport.apply(null, /** @type {any} */ (a))); }
function _chartExportRunExport(gd, val) {
    // Underlaget bestäms här, en gång (ett anrop av vyns exportMedSma).
    const underlag = _chartExportKarna(gd) ? _chartExportUnderlag(gd) : undefined;
    gd = _chartExportAktuell(gd);
    // Ett diagram från diagramkärnan utan något att exportera: ingen fil, ingenting på urklipp.
    if (underlag === null) return Promise.reject(new Error('Det finns inget att exportera i diagrammet.'));
    if (val === 'data-kopiera') return Promise.resolve(_copyMatrixToClipboard(chartExportRows(gd, underlag)));
    if (val === 'data-csv') {
        return Promise.resolve(_downloadCSV(chartExportRows(gd, underlag), chartExportFilename(gd, 'csv').replace(/\.csv$/, '')));
    }
    return _chartExportImage(gd, val, underlag);
}

/** Lägger exportknappen i diagrammets övre högra hörn. Idempotent. */
function _attachChartExport(graphDiv) {
    const gd = _chartExportEl(graphDiv);
    if (!gd || gd._chartExportAttached || !gd.parentElement) return;
    if (!exportTillaten(gd)) return;
    gd._chartExportAttached = true;
    const host = gd.parentElement;
    host.classList.add('chart-export-host');
    const menyId = `chart-export-${++_chartExportSeq}`;
    const wrap = document.createElement('div');
    wrap.className = 'chart-export';
    wrap.innerHTML =
        `<button type="button" class="chart-export-btn" aria-expanded="false" aria-controls="${menyId}" `
        + `aria-label="Exportera diagrammet ${esc(chartExportTitle(gd))}">${ikon('laddaNed', 14)} Exportera</button>`
        + `<div class="chart-export-meny" id="${menyId}" hidden>`
        + '<button type="button" data-chart-export="png-presentation">PNG, presentation (1920 × 1080)</button>'
        + '<button type="button" data-chart-export="png-dokument">PNG, dokument (1600 × 900)</button>'
        + '<button type="button" data-chart-export="svg">SVG (vektor, skarp i Word)</button>'
        + '<button type="button" data-chart-export="data-kopiera">Kopiera diagramdata</button>'
        + '<button type="button" data-chart-export="data-csv">Ladda ner diagramdata (CSV)</button>'
        + '<p class="chart-export-fel" role="alert" hidden></p>'
        + '</div>';
    wrap._gd = gd;
    host.insertBefore(wrap, gd);
}

function _chartExportStang(utom) {
    document.querySelectorAll('.chart-export-meny:not([hidden])').forEach(m => {
        if (m === utom) return;
        /** @type {HTMLElement} */ (m).hidden = true;
        const b = /** @type {HTMLElement} */ (m.parentElement).querySelector('.chart-export-btn');
        if (b) b.setAttribute('aria-expanded', 'false');
    });
}

document.addEventListener('click', e => {
    const btn = /** @type {HTMLElement} */ (e.target).closest('.chart-export-btn');
    if (btn) {
        const meny = /** @type {HTMLElement} */ (/** @type {HTMLElement} */ (btn.parentElement).querySelector('.chart-export-meny'));
        const oppna = /** @type {HTMLElement} */ (meny).hidden;
        _chartExportStang(meny);
        /** @type {HTMLElement} */ (meny).hidden = !oppna;
        btn.setAttribute('aria-expanded', String(oppna));
        if (oppna) meny.querySelector('button')?.focus();
        return;
    }
    const val = /** @type {HTMLElement} */ (e.target).closest('[data-chart-export]');
    if (val) {
        const wrap = /** @type {HTMLElement} */ (val.closest('.chart-export'));
        const fel = /** @type {HTMLElement} */ (wrap.querySelector('.chart-export-fel'));
        /** @type {HTMLElement} */ (fel).hidden = true;
        chartExportRun(wrap._gd, val.getAttribute('data-chart-export'))
            .then(() => {
                _chartExportStang();
                /** @type {HTMLInputElement} */ (wrap.querySelector('.chart-export-btn'))?.focus();   // fokus tillbaka dit man var
            })
            .catch(err => {
                fel.textContent = 'Exporten misslyckades: ' + ((err && err.message) || String(err));
                /** @type {HTMLElement} */ (fel).hidden = false;
            });
        return;
    }
    // En tabells exportmeny (.tabell-export) har egna knappar med egna lyssnare: menyn stängs när ett val gjorts.
    if (!/** @type {HTMLElement} */ (e.target).closest('.chart-export') || /** @type {HTMLElement} */ (e.target).closest('.tabell-export .chart-export-meny button')) _chartExportStang();
});
// Stäng menyn när tangentbordsfokus lämnar den (Tab ut).
document.addEventListener('focusout', e => {
    const wrap = /** @type {HTMLElement} */ (e.target).closest && /** @type {HTMLElement} */ (e.target).closest('.chart-export');
    if (!wrap) return;
    if (e.relatedTarget && wrap.contains(/** @type {Node} */ (e.relatedTarget))) return;
    const meny = wrap.querySelector('.chart-export-meny');
    if (meny && !/** @type {HTMLElement} */ (meny).hidden) _chartExportStang();
});
document.addEventListener('keydown', e => {
    if (e.key !== 'Escape') return;
    const oppen = document.querySelector('.chart-export-meny:not([hidden])');
    if (!oppen) return;
    _chartExportStang();
    /** @type {HTMLElement} */ (/** @type {HTMLInputElement} */ (oppen.parentElement).querySelector('.chart-export-btn'))?.focus();
});
// SPDX-License-Identifier: MIT
// Copyright 2026 Felix Jansson
// ====================================================================
// 11-markering.js — Länkade vyer: en markerad grupp framhävs i alla diagram
//
// Ett klick på ett märke som hör till ett BAS-intervall eller en yrkesgrupp (yrke inom BAS) markerar gruppen.
// Markeringen är gemensam för hela verktyget: varje diagram som ritar något för gruppen framhäver det och
// tonar ned resten, också i andra flikar, och tabellrader för gruppen framhävs. En rad nere till höger säger vad
// som är markerat och låter användaren öppna gruppdossiern eller ta bort markeringen. Ett klick till på samma
// grupp, eller Escape, tar bort den. Med Ctrl, Cmd eller Skift nedtryckt läggs gruppen TILL de markerade (eller
// tas bort ur dem), så att flera grupper kan jämföras.
//
// En datapunkt hör till en grupp genom fältet `markering` (se markeringFor): ['bas:C'] eller
// ['bas:C', 'grupp:207011|C']. Ett BAS framhäver sina yrkesgrupper; en yrkesgrupp framhäver sig själv och
// stapeln eller spannet för sitt BAS.
//
// Dataskydd: markeringen ändrar bara utseendet på märken som redan är ritade. Den ritar ingenting nytt, följer
// inte med i någon export (exporten ritas på nytt ur figuren) och sparas inte — den ligger i minnet och
// försvinner med "Rensa all data". Det går bara att markera det som går att klicka på, alltså det som visas.
// ====================================================================

let _markering = [];   // de markerade gruppernas nycklar, i den ordning de markerades

/** Fältet `markering` för en datapunkt: BAS-intervallet, och yrkesgruppen när `aid` är angiven. */
function markeringFor(bas, aid) {
    if (bas == null || bas === '') return [];
    const b = String(bas);
    if (aid == null || aid === '') return [`bas:${b}`];
    const m = String(aid).match(/^(\d+)/);
    return [`bas:${b}`, `grupp:${m ? m[1] : String(aid)}|${b}`];
}

/** De markerade gruppernas nycklar, eller null när inget är markerat. */
function diagramMarkering() { return _markering.length ? _markering.slice() : null; }

// Hör en datapunkt (eller tabellrad) med de här nycklarna till någon av de markerade grupperna?
function _mkTraff(nycklar, valda) {
    return (Array.isArray(valda) ? valda : [valda]).some(v => _mkTraffEn(nycklar, v));
}
function _mkTraffEn(nycklar, vald) {
    if (!Array.isArray(nycklar) || !nycklar.length) return false;
    if (nycklar.includes(vald)) return true;
    // En markerad yrkesgrupp framhäver också märket för sitt BAS, när märket gäller hela BAS-intervallet.
    if (vald.startsWith('grupp:')) {
        const bas = vald.slice(vald.indexOf('|') + 1);
        return nycklar.length === 1 && nycklar[0] === `bas:${bas}`;
    }
    return false;
}

function _mkEtikett(nyckel) {
    if (nyckel.startsWith('bas:')) return `BAS ${nyckel.slice(4)}`;
    const [aid, bas] = nyckel.slice(6).split('|');
    const rad = getData().find(r => r.bas === bas && String(r.yrke || '').startsWith(aid));
    return `${rad ? rad.yrke : aid} · BAS ${bas}`;
}

/**
 * Markerar gruppen med nyckeln. Utan `lagg` ersätter den det som är markerat (och ett klick till på den enda
 * markerade gruppen tar bort markeringen); med `lagg` läggs den till, eller tas bort om den redan är markerad.
 * `null` tar bort allt.
 */
function sattDiagramMarkering(nyckel, { lagg = false } = {}) {
    if (!nyckel) _markering = [];
    else if (lagg) _markering = _markering.includes(nyckel) ? _markering.filter(k => k !== nyckel) : [..._markering, nyckel];
    else _markering = _markering.length === 1 && _markering[0] === nyckel ? [] : [nyckel];
    if (typeof _rfMarkeraAlla === 'function') _rfMarkeraAlla();
    _mkTabeller();
    _mkRitaRad();
}

// ---- Tabeller ----
// En tabellrad hör till en grupp genom egenskapen `_markering` (satt av vyn; följer inte med när radens HTML
// kopieras till utskriften), data-markering (JSON-lista med nycklar), data-rad ("aid|bas", tabellen i
// Jämförelsestatistik) eller en knapp i raden som bär yrke och BAS (prioriteringstabellen).
function _mkRadNycklar(tr) {
    if (Array.isArray(tr._markering)) return tr._markering;
    if (tr.dataset.markering) { try { const n = JSON.parse(tr.dataset.markering); return Array.isArray(n) ? n : null; } catch (_e) { return null; } }
    if (tr.dataset.rad && tr.dataset.rad.includes('|')) { const [aid, bas] = tr.dataset.rad.split('|'); return markeringFor(bas, aid); }
    const knapp = tr.querySelector('[data-yrke][data-bas]');
    return knapp ? markeringFor(knapp.getAttribute('data-bas'), knapp.getAttribute('data-yrke')) : null;
}
/** Framhäver tabellraderna för de markerade grupperna. Anropas när markeringen ändras och när en flik har ritats. */
function _mkTabeller() {
    const valda = _markering;
    for (const tr of document.querySelectorAll('tbody tr')) {
        const nycklar = _mkRadNycklar(tr);
        const traff = !!(valda.length && nycklar && nycklar.length && _mkTraff(nycklar, valda));
        if (traff !== tr.classList.contains('rad-markerad')) tr.classList.toggle('rad-markerad', traff);
    }
}
// Ett klick på en tabellrad som hör till en grupp markerar den — men inte ett klick på en knapp, länk eller ett fält i raden.
document.addEventListener('click', e => {
    const t = e.target;
    if (!t || !/** @type {HTMLElement} */ (t).closest || /** @type {HTMLElement} */ (t).closest('button, a, input, select, label, textarea, summary')) return;
    const tr = /** @type {HTMLElement} */ (t).closest('tbody tr');
    if (!tr) return;
    const nycklar = _mkRadNycklar(tr);
    if (nycklar && nycklar.length) sattDiagramMarkering(nycklar[nycklar.length - 1], { lagg: e.ctrlKey || e.metaKey || e.shiftKey });
});

/**
 * Framhäver det markerade i ett ritat diagram: märken som hör till markeringen behåller sitt utseende och får
 * data-markerad, övriga märken med en grupp tonas ned. Ett diagram där inget märke hör till markeringen lämnas
 * orört — det har inget att säga om gruppen. Märken utan grupp (linjer, band, referenser) rörs aldrig.
 */
function _mkTillampa(el) {
    const figur = el && el._figur;
    if (!figur || !el.querySelector) return;
    const vald = _markering.length ? _markering : null;
    if (el._rfPensel) return;   // ett penslat område bestämmer just nu vilka punkter som framhävs i det här diagrammet
    const marken = [...el.querySelectorAll(':scope > svg [data-l][data-i]')].map(m => {
        const l = figur.lager[Number(m.getAttribute('data-l'))];
        const d = l && Array.isArray(l.data) ? l.data[Number(m.getAttribute('data-i'))] : null;
        return { m, nycklar: d && d.markering };
    }).filter(o => Array.isArray(o.nycklar) && o.nycklar.length);
    const traffar = vald ? marken.filter(o => _mkTraff(o.nycklar, vald)) : [];
    for (const o of marken) {
        const traff = traffar.includes(o);
        if (traffar.length && !traff) o.m.setAttribute('opacity', '0.22'); else o.m.removeAttribute('opacity');
        if (traff) o.m.setAttribute('data-markerad', ''); else o.m.removeAttribute('data-markerad');
    }
}

// Raden som säger vad som är markerat, med gruppdossiern (när EN yrkesgrupp med dossier är markerad) och Ta bort.
// Den står överst i innehållet, på samma plats i alla flikar, och följer med överst i fönstret när sidan rullas
// (position: sticky) — den ligger aldrig över det man läser.
function _mkPlacera(rad) {
    const yta = document.querySelector('.content-body') || document.body;
    if (rad.parentNode !== yta || yta.firstElementChild !== rad) yta.insertBefore(rad, yta.firstChild);
}
function _mkRitaRad() {
    let rad = document.getElementById('markering-rad');
    if (!_markering.length) { if (rad) rad.remove(); return; }
    if (!rad) {
        rad = document.createElement('div');
        rad.id = 'markering-rad';
        rad.className = 'markering-rad';
        rad.setAttribute('role', 'status');
        rad.addEventListener('click', e => {
            const knapp = /** @type {HTMLElement} */ (e.target).closest('button[data-markering]');
            if (!knapp) return;
            const vad = knapp.getAttribute('data-markering');
            if (vad === 'dossier') { const k = _mkDossierNyckel(); if (k) openGruppdossier(k); }
            else if (vad === 'borra') nedborrningTillUtforska();
            else sattDiagramMarkering(null);
        });
    }
    _mkPlacera(rad);
    rad.textContent = '';
    const text = document.createElement('span');
    const namn = _markering.map(_mkEtikett);
    text.textContent = `Markerat i alla diagram: ${namn.slice(0, 3).join(' · ')}${namn.length > 3 ? ` + ${namn.length - 3} till` : ''}`;
    text.title = namn.join('\n');
    rad.appendChild(text);
    if (_mkDossierNyckel()) rad.appendChild(_mkKnapp('dossier', 'Öppna gruppdossier'));
    if (_mkBorrBas() != null) {
        const b = _mkKnapp('borra', 'Visa yrkesgrupperna');
        b.title = 'Öppnar Utforska med yrkesgrupperna i BAS-intervallet. Där visas också grupper under tröskeln, markerade; de följer inte med i en export om du inte väljer det.';
        rad.appendChild(b);
    }
    rad.appendChild(_mkKnapp('rensa', 'Ta bort markeringen'));
    // Tipset står i verktygstipset på raden, inte som en egen text.
    rad.title = _markering.length === 1 ? 'Ctrl-klicka på en annan grupp för att lägga till den. Escape tar bort markeringen.' : 'Escape tar bort markeringen.';
}
function _mkKnapp(vad, text) {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'btn-table-tool';
    b.setAttribute('data-markering', vad);
    b.textContent = text;
    return b;
}
// Gruppdossiern finns bara för en yrkesgrupp med minst tröskeln personer.
function _mkDossierNyckel() {
    if (_markering.length !== 1 || !_markering[0].startsWith('grupp:')) return null;
    const nyckel = _markering[0].slice(6);
    return typeof gruppdossierCandidates === 'function' && gruppdossierCandidates().some(c => c.key === nyckel) ? nyckel : null;
}

// ---- Nedborrning: från ett markerat BAS-intervall till dess yrkesgrupper i Utforska ----
// Utforska öppnas med urvalet satt till BAS-intervallet och raderna "yrkesgrupp inom BAS". Det urval och de val
// användaren hade där innan sparas i minnet, så att raden ovanför diagrammet kan återställa dem och gå tillbaka
// till fliken man kom från. Utforska visar grupper under tröskeln markerade — raden säger det.
/** @type {any} */
let _mkTillbaka = null;   // { bas, urval, gruppVillkor, rad, kolumn, flik } eller null

function _mkBorrBas() {
    return _markering.length === 1 && _markering[0].startsWith('bas:') && typeof explorerSattUrval === 'function' ? _markering[0].slice(4) : null;
}
function nedborrningTillUtforska() {
    const bas = _mkBorrBas();
    if (bas == null) return;
    const rad = document.getElementById('explore-rad'), kolumn = document.getElementById('explore-kolumn');
    if (!rad || !kolumn) return;
    const aktiv = document.querySelector('.nav-item.active');
    const innan = _mkTillbaka || { ...explorerUrval(), rad: /** @type {HTMLInputElement} */ (rad).value, kolumn: /** @type {HTMLInputElement} */ (kolumn).value, flik: aktiv ? aktiv.getAttribute('data-tab') : null };
    _mkTillbaka = { ...innan, bas };
    explorerSattUrval({ lage: 'alla', villkor: [{ falt: 'bas', op: 'enAv', varde: [bas] }] }, []);
    /** @type {HTMLInputElement} */ (rad).value = 'aidbas';
    /** @type {HTMLInputElement} */ (kolumn).value = 'ingen';
    _mkBorrRad();
    const nav = document.querySelector('.nav-item[data-tab="utforska"]');
    if (nav && nav !== aktiv) /** @type {HTMLElement} */ (nav).click(); else if (typeof renderExplorer === 'function') renderExplorer();
}
function nedborrningTillbaka() {
    const t = _mkTillbaka;
    if (!t) return;
    _mkTillbaka = null;
    explorerSattUrval(t.urval, t.gruppVillkor);
    const rad = document.getElementById('explore-rad'), kolumn = document.getElementById('explore-kolumn');
    if (rad) /** @type {HTMLInputElement} */ (rad).value = t.rad;
    if (kolumn) /** @type {HTMLInputElement} */ (kolumn).value = t.kolumn;
    _mkBorrRad();
    const nav = t.flik && t.flik !== 'utforska' ? document.querySelector(`.nav-item[data-tab="${t.flik}"]`) : null;
    if (nav) /** @type {HTMLElement} */ (nav).click(); else if (typeof renderExplorer === 'function') renderExplorer();
}
/** Glömmer vägen tillbaka ("Rensa all data"): det sparade urvalet namnger grupper. */
function nedborrningGlom() { _mkTillbaka = null; _mkBorrRad(); }
function _mkBorrRad() {
    const el = document.getElementById('explore-nedborrning');
    if (!el) return;
    el.textContent = '';
    el.hidden = !_mkTillbaka;
    if (!_mkTillbaka) return;
    el.appendChild(document.createTextNode(`Du kom hit från BAS ${_mkTillbaka.bas}: urvalet är satt till det BAS-intervallet och raderna till yrkesgrupp inom BAS. `
        + `Grupper med färre än ${kInstalld()} personer följer inte med i en export om du inte kryssar i rutan. `));
    const b = _mkKnapp('tillbaka', 'Tillbaka till föregående urval');
    b.addEventListener('click', nedborrningTillbaka);
    el.appendChild(b);
}

document.addEventListener('keydown', e => {
    if (e.key !== 'Escape' || document.querySelector('.modal[style*="flex"]')) return;
    if (typeof _rfPenselRensaAlla === 'function') _rfPenselRensaAlla();
    if (_markering.length) sattDiagramMarkering(null);
});
