// ---- Datavalideringsrapport (efter CSV-parse) ----
/**
 * Reality-check-panel.
 *
 * Före HR börjar tolka analyserna, kör en sanity-check av att underlaget
 * är rimligt. Fångar t.ex. fel kolumnmappning (95 % män), orealistiska
 * åldrar (medianålder 19 år) eller löner som lämnats i ören istället för
 * kronor. Skyddar mot tysta tolkningsfel.
 *
 * Klassificering av varje check:
 *   ✅ grönt   — inom rimligt intervall
 *   ⚠ gult    — utanför typiskt intervall men inte omöjligt
 *   🔴 rött   — extremt avvikande, kontrollera mappningen
 */
function renderRealityCheck() {
    const wrap = document.getElementById('reality-check');
    if (!wrap) return;
    if (!state.data.length) { wrap.style.display = 'none'; wrap.innerHTML = ''; return; }

    const d = state.data;
    const n = d.length;

    // Check 1: könsfördelning
    const nKv = d.filter(r => r.kon.includes('kvinna')).length;
    const pctKv = n > 0 ? nKv / n * 100 : 0;
    let konStatus, konMsg;
    if (pctKv >= 30 && pctKv <= 70) {
        konStatus = 'ok';
        konMsg = `Könsfördelning: <strong>${svPct(pctKv, 1)} kvinnor, ${svPct((100 - pctKv), 1)} män</strong>. Inom typiskt kommunalt intervall (30–70 %).`;
    } else if (pctKv >= 15 && pctKv <= 85) {
        konStatus = 'warn';
        konMsg = `Könsfördelning: <strong>${svPct(pctKv, 1)} kvinnor, ${svPct((100 - pctKv), 1)} män</strong>. Skev men inte omöjlig — vanligt i specialiserade organisationer (t.ex. teknisk eller socialtjänst).`;
    } else {
        konStatus = 'err';
        konMsg = `Könsfördelning: <strong>${svPct(pctKv, 1)} kvinnor, ${svPct((100 - pctKv), 1)} män</strong>. Extremt avvikande — <strong>kontrollera att kön-kolumnen är korrekt mappad</strong>. En vanlig felkälla är att kolumnen innehåller ett ID istället för "Kvinna"/"Man".`;
    }

    // Check 2: medianålder
    const ages = d.map(r => r.alder).filter(a => a > 0);
    const medAge = ages.length ? Stat.median(ages) : 0;
    const minAge = ages.length ? Math.min(...ages) : 0;
    const maxAge = ages.length ? Math.max(...ages) : 0;
    let alderStatus, alderMsg;
    if (medAge >= 38 && medAge <= 55) {
        alderStatus = 'ok';
        alderMsg = `Medianålder: <strong>${svTal(medAge, 0)} år</strong> (spann ${minAge}–${maxAge}). Inom typiskt kommunalt intervall (38–55 år).`;
    } else if (medAge >= 30 && medAge <= 60) {
        alderStatus = 'warn';
        alderMsg = `Medianålder: <strong>${svTal(medAge, 0)} år</strong> (spann ${minAge}–${maxAge}). Något utanför typiskt intervall — kontrollera om datan kommer från en specifik organisation med ovanlig demografi.`;
    } else {
        alderStatus = 'err';
        alderMsg = `Medianålder: <strong>${svTal(medAge, 0)} år</strong> (spann ${minAge}–${maxAge}). Extremt avvikande — <strong>kontrollera ålders-kolumnen</strong>. Vanlig felkälla är att ett anställningsdatum lästs in som ålder, eller att kolumnen visar år för anställning istället.`;
    }

    // Check 3: lönespridning (P10, median, P90)
    const lons = d.map(r => r.lon).filter(l => l > 0);
    const p10 = Stat.quantile(lons, 0.10);
    const p50 = Stat.median(lons);
    const p90 = Stat.quantile(lons, 0.90);
    const fmtK = v => Math.round(v).toLocaleString('sv-SE') + ' kr';
    let lonStatus, lonMsg;
    if (p50 >= 25000 && p50 <= 60000) {
        lonStatus = 'ok';
        lonMsg = `Lönespridning: P10 <strong>${fmtK(p10)}</strong> · median <strong>${fmtK(p50)}</strong> · P90 <strong>${fmtK(p90)}</strong>. Inom typiskt svenskt kommunintervall.`;
    } else if (p50 >= 15000 && p50 < 25000) {
        lonStatus = 'warn';
        lonMsg = `Lönespridning: P10 <strong>${fmtK(p10)}</strong> · median <strong>${fmtK(p50)}</strong> · P90 <strong>${fmtK(p90)}</strong>. Låg medianlön — finns deltidsanställda räknade som heltid i underlaget? Lönen bör vara heltidsekvivalent.`;
    } else if (p50 > 60000 && p50 <= 90000) {
        lonStatus = 'warn';
        lonMsg = `Lönespridning: P10 <strong>${fmtK(p10)}</strong> · median <strong>${fmtK(p50)}</strong> · P90 <strong>${fmtK(p90)}</strong>. Hög medianlön — typisk för specialistorganisationer eller äldre data har lönerevisionerats.`;
    } else {
        lonStatus = 'err';
        lonMsg = `Lönespridning: P10 <strong>${fmtK(p10)}</strong> · median <strong>${fmtK(p50)}</strong> · P90 <strong>${fmtK(p90)}</strong>. Extremt avvikande — <strong>kontrollera lön-kolumnen</strong>. Vanlig felkälla: lönen är angiven i ören (multiplicera med 1/100), årslön istället för månadslön (dela med 12), eller deltidsproportionerad istället för heltidsekvivalent.`;
    }

    // (BAS-maskeringen bedöms nu av kriteriet Jämförbarhet i Underlagets kvalitet, ADR-19.)

    // Check 5: FTE-heuristik — andel löner under heltidsgolvet.
    // Check 3 fångar bara när MEDIANEN är låg; den vanliga felmoden är blandade
    // heltids- och ej omräknade deltidslöner (normal median, fet låg svans).
    // Heltidslöner i kommunal sektor understiger i praktiken inte ~20 000 kr/mån;
    // deltid på 50–75 % hamnar ofta på 12–18 000 kr.
    const FTE_GOLV = 20000;
    const nLow = lons.filter(l => l < FTE_GOLV).length;
    const pctLow = lons.length ? (nLow / lons.length) * 100 : 0;
    let fteStatus, fteMsg;
    if (nLow === 0) {
        fteStatus = 'ok';
        fteMsg = `Inga löner under ${fmtK(FTE_GOLV)}/mån — förenligt med heltidsomräknade (FTE) löner, som verktyget förutsätter.`;
    } else if (pctLow <= 2) {
        fteStatus = 'ok';
        fteMsg = `${nLow} lön${nLow === 1 ? '' : 'er'} (${svPct(pctLow, 1)}) under ${fmtK(FTE_GOLV)}/mån — enstaka undantag (t.ex. ungdomsanställningar) är normalt. Verktyget förutsätter heltidsomräknade (FTE) löner.`;
    } else if (pctLow <= 15) {
        fteStatus = 'warn';
        fteMsg = `<strong>${nLow}</strong> löner (<strong>${svPct(pctLow, 1)}</strong>) ligger under ${fmtK(FTE_GOLV)}/mån — kontrollera att månadslönerna är <strong>heltidsomräknade (FTE)</strong>. Ej omräknade deltidslöner snedvrider hela könsanalysen, eftersom deltid oftast är kvinnodominerad.`;
    } else {
        fteStatus = 'err';
        fteMsg = `<strong>${nLow}</strong> löner (<strong>${svPct(pctLow, 1)}</strong>) ligger under ${fmtK(FTE_GOLV)}/mån — underlaget ser <strong>inte</strong> heltidsomräknat ut. Exportera lönerna som heltidsekvivalenter (FTE) ur lönesystemet innan analysen används; ej omräknade deltidslöner gör könsjämförelserna missvisande.`;
    }

    const icon = s => s === 'ok' ? ikon('bock') : s === 'warn' ? ikon('statusVarning') : ikon('statusKritisk');
    const allStatuses = [konStatus, alderStatus, lonStatus, fteStatus];
    const hasErr = allStatuses.includes('err');
    const hasWarn = allStatuses.includes('warn');
    const headerClass = hasErr ? 'has-err' : hasWarn ? 'has-warn' : 'all-ok';
    wrap.style.display = 'block';
    wrap.className = 'reality-check ' + headerClass;
    wrap.innerHTML = `
        <h4 class="text-dampad-xs versal marg-0-0-6">Rimlighet i detalj</h4>
        <p class="text-dampad-sm marg-0-0-12">
            Fångar typiska mappningsfel (fel kolumn, fel enhet, fel kön-kodning). Verktyget kan inte
            avgöra om värdena är "rätt" — bara att de är inom rimliga intervall.
        </p>
        <ul class="reality-list utan-punkter marg-0 pad-0">
            <li class="rc-${konStatus} rund-0-4-4-0 fs-md lh-1_5 marg-b-6 pad-8-10">
                <span class="mr-6">${icon(konStatus)}</span>${konMsg}
            </li>
            <li class="rc-${alderStatus} rund-0-4-4-0 fs-md lh-1_5 marg-b-6 pad-8-10">
                <span class="mr-6">${icon(alderStatus)}</span>${alderMsg}
            </li>
            <li class="rc-${lonStatus} rund-0-4-4-0 fs-md lh-1_5 marg-b-6 pad-8-10">
                <span class="mr-6">${icon(lonStatus)}</span>${lonMsg}
            </li>
            <li class="rc-${fteStatus} rund-0-4-4-0 fs-md lh-1_5 marg-b-6 pad-8-10">
                <span class="mr-6">${icon(fteStatus)}</span>${fteMsg}
            </li>
        </ul>
    `;
}

function renderDataValidationReport() {
    const wrap = document.getElementById('data-validation-report');
    if (!wrap) return;
    if (!state.data.length) { wrap.style.display = 'none'; wrap.innerHTML = ''; return; }

    const da = state.dataAudit || {};
    const totalRaw = da.totalRaw || 0;
    const excludedNoBas = da.excludedNoBas || 0;
    const excludedZeroLon = da.excludedZeroLon || 0;
    const excludedMissingKon = da.excludedMissingKon || 0;
    const invalidLon = da.invalidLon || 0;
    const invalidAlder = da.invalidAlder || 0;
    const invalidLonExamples = da.invalidLonExamples || [];
    const invalidAlderExamples = da.invalidAlderExamples || [];
    const missingKonExamples = da.missingKonExamples || [];
    const used = state.data.length;

    // Räkna varningar
    const outliers = detectOutliers(3);
    const bas = getBasIntervals();
    const singleSexBas = bas.filter(b => {
        const sub = state.data.filter(r => r.bas === b);
        if (sub.length < 3) return false;
        const hasKv = sub.some(r => r.kon.includes('kvinna'));
        const hasMa = sub.some(r => r.kon === 'man' || r.kon === 'män');
        return !hasKv || !hasMa;
    }).length;
    const kMaskedBas = bas.filter(b => state.data.filter(r => r.bas === b).length < kInstalld()).length;

    // Konsistenskontroll
    const dataBas = [...new Set(state.data.map(r => r.bas))].sort();
    const dataAids = [...new Set(state.data.map(r => { const m = r.yrke.match(/^(\d+)/); return m ? m[1] : null; }).filter(Boolean))];
    /** @type {any} */ let polStatus = null;
    /** @type {any} */ let statStatus = null;
    if (state.policy.length) {
        const polBas = state.policy.map(p => p.bas);
        const missing = dataBas.filter(b => !polBas.includes(b));
        polStatus = { ok: missing.length === 0, missing };
    }
    if (state.statistik.length) {
        const statAids = [...new Set(state.statistik.map(s => s.aid))];
        const missing = dataAids.filter(a => !statAids.includes(a));
        statStatus = { ok: missing.length === 0, missing };
    }

    const warnings = outliers.length + singleSexBas + (polStatus && !polStatus.ok ? 1 : 0) + (statStatus && !statStatus.ok ? 1 : 0);
    const hasWarnings = warnings > 0;

    const fmt = n => n.toLocaleString('sv-SE');

    wrap.className = 'data-validation-report' + (hasWarnings ? ' has-warnings' : '');
    wrap.style.display = 'block';
    wrap.innerHTML = `
        <h4 class="text-dampad-xs versal marg-14-0-8">Inläsning & varningar${hasWarnings ? ' — ' + warnings + ' att granska' : ''}</h4>
        <div class="dvr-grid">
            <div class="dvr-section">
                <h4>Från fil till analys</h4>
                <div class="dvr-row ok"><span>Total rader i fil:</span><span class="dvr-value">${fmt(totalRaw)}</span></div>
                ${excludedNoBas > 0 ? `<div class="dvr-row warn"><span><span class="dvr-icon">−</span>Saknar BAS:</span><span class="dvr-value">${fmt(excludedNoBas)}</span></div>` : ''}
                ${excludedZeroLon > 0 ? `<div class="dvr-row warn"><span><span class="dvr-icon">−</span>Lön ≤ 0:</span><span class="dvr-value">${fmt(excludedZeroLon)}</span></div>` : ''}
                ${excludedMissingKon > 0 ? `<div class="dvr-row warn"><span><span class="dvr-icon">−</span>Saknar/okänt kön:${missingKonExamples.length ? ' <span class="text-dampad-xs">ex: ' + missingKonExamples.map(e => '"' + esc(e) + '"').join(', ') + '</span>' : ''}</span><span class="dvr-value">${fmt(excludedMissingKon)}</span></div>` : ''}
                ${invalidLon > 0 ? `<div class="dvr-row warn"><span><span class="dvr-icon">${ikon('statusVarning')}</span>Ogiltig lön (text):${invalidLonExamples.length ? ' <span class="text-dampad-xs">ex: ' + invalidLonExamples.map(e => '"' + esc(e) + '"').join(', ') + '</span>' : ''}</span><span class="dvr-value">${fmt(invalidLon)}</span></div>` : ''}
                ${invalidAlder > 0 ? `<div class="dvr-row warn"><span><span class="dvr-icon">${ikon('statusVarning')}</span>Ogiltig ålder (text):${invalidAlderExamples.length ? ' <span class="text-dampad-xs">ex: ' + invalidAlderExamples.map(e => '"' + esc(e) + '"').join(', ') + '</span>' : ''}</span><span class="dvr-value">${fmt(invalidAlder)}</span></div>` : ''}
                <div class="dvr-row dvr-total ok"><span>= Inlästa:</span><span class="dvr-value">${fmt(used)}</span></div>
                ${totalRaw > 0 ? `<div class="text-dampad-xs marg-t-4">Användbarhetsgrad: <strong>${svPct((used / Math.max(1, totalRaw) * 100), 1)}</strong> av filens rader.</div>` : ''}
                ${(invalidLon > 0 || invalidAlder > 0 || excludedMissingKon > 0) ? `<div class="farg-varning fs-xs lh-1_4 marg-t-6">Granska om antalet är högt — kan signalera ett systematiskt fel i exporten från lönesystemet. Exempel-värdena ovan visar de första 3 mönstren som föll ut, för felsökning.</div>` : ''}
            </div>

            <div class="dvr-section">
                <h4>Datavarningar</h4>
                ${outliers.length > 0
                    ? `<div class="dvr-row warn"><span><span class="dvr-icon">${ikon('statusVarning')}</span>Extremvärden (mer än 3 standardavvikelser):</span><span class="dvr-value">${outliers.length}</span></div>`
                    : `<div class="dvr-row ok"><span><span class="dvr-icon">${ikon('bock')}</span>Inga extremvärden (mer än 3 standardavvikelser)</span><span></span></div>`}
                ${singleSexBas > 0
                    ? `<div class="dvr-row warn"><span><span class="dvr-icon">${ikon('statusVarning')}</span>Enkönade BAS:</span><span class="dvr-value">${singleSexBas}</span></div>`
                    : `<div class="dvr-row ok"><span><span class="dvr-icon">${ikon('bock')}</span>Alla BAS har båda kön</span><span></span></div>`}
                ${kMaskedBas > 0
                    ? `<div class="dvr-row ok"><span><span class="dvr-icon">${ikon('las')}</span>BAS under minsta gruppstorlek (n&lt;${kInstalld()}, redovisas inte i exporterna):</span><span class="dvr-value">${kMaskedBas}</span></div>`
                    : ''}
                <div class="text-dampad-xs lh-1_4 marg-t-6">${outliers.length > 0 ? 'Granska Outliers-detektorn nedan för detaljer.' : 'Inga uppenbara registerfel hittades.'}</div>
            </div>

            <div class="dvr-section">
                <h4>Konsistens med referensfiler</h4>
                ${polStatus
                    ? polStatus.ok
                        ? `<div class="dvr-row ok"><span><span class="dvr-icon">${ikon('bock')}</span>${esc(referensKortnamn())}:</span><span class="dvr-value">OK</span></div>`
                        : `<div class="dvr-row warn"><span><span class="dvr-icon">${ikon('statusVarning')}</span>${esc(referensKortnamn())}:</span><span class="dvr-value">${polStatus.missing.length} BAS saknas</span></div>`
                    : ''}
                ${statStatus
                    ? statStatus.ok
                        ? `<div class="dvr-row ok"><span><span class="dvr-icon">${ikon('bock')}</span>Jämförelsestatistik:</span><span class="dvr-value">OK</span></div>`
                        : `<div class="dvr-row warn"><span><span class="dvr-icon">${ikon('statusVarning')}</span>Jämförelsestatistik:</span><span class="dvr-value">${statStatus.missing.length} AID saknas</span></div>`
                    : '<div class="dvr-row f-dampad"><span><span class="dvr-icon">' + ikon('statusIngen') + '</span>Jämförelsestatistik:</span><span>Ej uppladdad</span></div>'}
                <div class="text-dampad-xs lh-1_4 marg-t-6">Detaljer i konsistens-bannern nedan.</div>
            </div>
        </div>
    `;
}

// Underlagets kvalitet (ADR-19): rimlighetskontrollen och inläsningsrapporten är
// underlag i panelen; statusen kommer från bedomningUnderlag().
// Anropas efter renderRealityCheck() + renderDataValidationReport().
function syncDatakvalitetPanel() {
    renderUnderlagetsKvalitet();
}

// ---- Konsistenscheck mellan filer ----
function renderConsistencyBanner() {
    const wrap = document.getElementById('consistency-banner-container');
    if (!wrap) return;
    if (!state.data.length) { wrap.innerHTML = ''; return; }

    const issues = [];
    const dataBas = [...new Set(state.data.map(d => d.bas).filter(Boolean))].sort();
    const dataAids = [...new Set(state.data.map(d => { const m = d.yrke.match(/^(\d+)/); return m ? m[1] : null; }).filter(Boolean))];

    // Ställningstagande
    if (state.policy.length) {
        const polBas = state.policy.map(p => p.bas);
        const dataNotInPol = dataBas.filter(b => !polBas.includes(b));
        const polNotInData = polBas.filter(b => !dataBas.includes(b));
        if (dataNotInPol.length) issues.push(`<strong>${esc(referensKortnamn())}:</strong> ${dataNotInPol.length} BAS-intervall saknas (<code>${dataNotInPol.map(esc).join(', ')}</code>) — analyserna kan inte jämföra dessa mot policy.`);
        // Den inbyggda målbilden täcker A–K avsiktligt; att underlaget saknar några BAS är inget fynd.
        if (polNotInData.length && state.policyKalla !== 'demo') issues.push(`<strong>${esc(referensKortnamn())}:</strong> ${polNotInData.length} BAS-intervall finns i policy men inte i strukturdata (<code>${polNotInData.map(esc).join(', ')}</code>).`);
    }

    // Jämförelsestatistik — visa AID + yrkesetikett
    if (state.statistik.length) {
        const statAids = [...new Set(state.statistik.map(s => s.aid))];
        const dataAidNotInStat = dataAids.filter(a => !statAids.includes(a));
        // Bygg AID → yrkesnamn-uppslagning från strukturdatan
        const aidToYrke = {};
        state.data.forEach(d => {
            const m = d.yrke.match(/^(\d+)/);
            const a = m ? m[1] : null;
            if (a && !aidToYrke[a]) aidToYrke[a] = d.yrke;
        });
        if (dataAidNotInStat.length) {
            const display = dataAidNotInStat.slice(0, 6)
                .map(a => `<code>${esc(aidToYrke[a] || a)}</code>`)
                .join(', ');
            const more = dataAidNotInStat.length > 6 ? ` … och ${dataAidNotInStat.length - 6} till` : '';
            issues.push(`<strong>Jämförelsestatistik:</strong> ${dataAidNotInStat.length} AID-koder i strukturdatan saknar matchning i jämförelsestatistiken (${display}${more}) — dessa yrken kan inte jämföras med statistiken.`);
        }
    }

    if (!issues.length) {
        if (state.policy.length || state.statistik.length) {
            wrap.innerHTML = `<div class="consistency-banner ok">${ikon('bock')} <strong>Konsistens-kontroll OK:</strong> Inläst data matchar väl mot uppladdade referensfiler.</div>`;
        } else {
            wrap.innerHTML = '';
        }
        return;
    }
    wrap.innerHTML = `<div class="consistency-banner">${ikon('statusVarning')} <strong>Konsistens-kontroll: ${issues.length} varning${issues.length>1?'ar':''}</strong><ul>${issues.map(i => `<li>${i}</li>`).join('')}</ul></div>`;
}
// SPDX-License-Identifier: MIT
// Copyright 2026 Felix Jansson
// ============================================================================
// ÅTGÄRDSLISTA — samlad checklist från alla flikar
// ============================================================================
// buildActionChecklist är UTTÖMMANDE — den samlar varje grupp/par/flagga
//   som HR behöver agera på, grupperad efter kategori (AKUT, § 3:10, EU-utred,
//   datakvalitet). HR kan klicka av punkterna när de hanterat dem.
//   State sparas på state._actionChecklist (i minnet — försvinner vid reload).

// Tal i punkternas texter: decimalkomma och belopp utan tecken — riktningen skrivs med ord.
const _agPct = v => Math.abs(v).toFixed(1).replace('.', ',');
const _agTal = (v, dec) => v.toFixed(dec).replace('.', ',');
const _agRiktning = v => (v < 0 ? 'lägre' : 'högre');

/**
 * Bygger en uttömmande lista av åtgärdspunkter från alla analysflikar.
 * Varje punkt har stabilt id så användarens "klar"-markering kvarstår även
 * om listan regenereras efter dataändring (samma grupp = samma id).
 *
 * @returns {Array<{id, kategori, prioritet, titel, detalj, tab, källa}>}
 */
function buildActionChecklist({ endastGrupper = false } = {}) {
    /** @type {any[]} */
    const items = [];
    if (!state.data.length) return items;

    // Punkterna per grupp (prioriteringen och likvärdighetsparen) bär AID-koden; sektorsöversikten
    // räknar bara dem och bygger därför inte de tunga, organisationsövergripande delarna.
    if (!endastGrupper) {
        // === 1. Underlagets kvalitet (ADR-19) — en punkt per kriterium som inte är OK ===
        try {
            const uk = (typeof bedomningUnderlag === 'function') ? bedomningUnderlag() : null;
            if (uk) uk.kriterier.filter(c => c.status !== 'ok').forEach(c => items.push({
                id: 'dq-' + c.id,
                kategori: 'Underlagets kvalitet',
                prioritet: c.status === 'kritisk' ? 'hög' : 'medel',
                titel: `${c.namn}: ${c.status === 'kritisk' ? 'kritisk' : 'varning'}`,
                detalj: c.text,
                tab: 'dashboard',
                källa: 'Underlagets kvalitet'
            }));
            if (state.dataAudit) {
                const da = state.dataAudit;
                if ((da.excludedMissingKon || 0) > 0) {
                    items.push({
                        id: 'dq-kon',
                        kategori: 'Datakvalitet',
                        prioritet: 'hög',
                        titel: `${da.excludedMissingKon} rad${da.excludedMissingKon === 1 ? '' : 'er'} saknar kön och exkluderades`,
                        detalj: 'Komplettera källfilen så fler personer kan ingå i analysen.',
                        tab: 'dashboard',
                        källa: 'CSV-uppladdning'
                    });
                }
                if ((da.invalidLon || 0) > 0) {
                    items.push({
                        id: 'dq-lon',
                        kategori: 'Datakvalitet',
                        prioritet: 'medel',
                        titel: `${da.invalidLon} rad${da.invalidLon === 1 ? '' : 'er'} med ogiltig lön`,
                        detalj: 'Kontrollera att lönekolumnen innehåller siffror, inte text. Se exempel i datakvalitetsrapporten.',
                        tab: 'dashboard',
                        källa: 'CSV-uppladdning'
                    });
                }
            }
        } catch (e) { rapporteraFel('Att göra: underlagets kvalitet', e); }

        // === Lika arbete: rått gap > 5 % i jämförbara BAS (samma regel som kompliansen) ===
        try {
            const d = getData();
            const jb = _dqJamforbaraBas(d, kInstalld());
            const reg = runOLSRegression();
            const perBas = (reg && !reg.error && reg.perBas) ? reg.perBas : [];
            jb.jamforbara.forEach(b => {
                const df = d.filter(r => r.bas === b);
                const kv = df.filter(r => r.kon.includes('kvinna')).map(r => r.lon);
                const ma = df.filter(r => r.kon === 'man' || r.kon === 'män').map(r => r.lon);
                const gap = (Stat.median(kv) / Stat.median(ma)) * 100 - 100;
                if (Math.abs(gap) <= 5) return;
                const pb = perBas.find(p => p.bas === b && p.status === 'ok');
                const forklaring = pb
                    ? (Math.abs(pb.gapPct) <= 5
                        ? ` Efter hänsyn till ålder har kvinnor ${_agPct(pb.gapPct)} % ${_agRiktning(pb.gapPct)} lön — under 5 %.`
                        : ` Efter hänsyn till ålder har kvinnor ${_agPct(pb.gapPct)} % ${_agRiktning(pb.gapPct)} lön.`)
                    : '';
                items.push({
                    id: 'gap-bas-' + b, kategori: 'Lika arbete', prioritet: 'medel',
                    titel: `BAS ${b}: kvinnors medianlön ${andelAvMan(gap)} av mäns`,   // rå skillnad: samma form som i Lika arbete
                    detalj: `Rå skillnad över 5 % i ett jämförbart BAS-intervall.${forklaring} Pröva om skillnaden har sakliga skäl.`,
                    tab: 'matrix', källa: 'Lika arbete'
                });
            });
        } catch (e) { rapporteraFel('Att göra: lika arbete per BAS', e); }

        // === 1b. Oförklarat gap för hela organisationen (regressionen) ===
        try {
            const reg = runOLSRegression();
            if (reg && !reg.error && reg.pValue < 0.05) {
                items.push({
                    id: 'reg-oforklarat', kategori: 'Lika arbete',
                    prioritet: Math.abs(reg.konPct) > 5 ? 'hög' : 'medel',
                    titel: `Oförklarat lönegap för hela organisationen: kvinnor ${_agPct(reg.konPct)} % ${_agRiktning(reg.konPct)} lön än män (efter ålder och BAS)`,
                    detalj: 'Ett oförklarat gap är inte samma sak som ett osakligt. Pröva skillnaden per yrkesgrupp i Lika arbete.',
                    tab: 'matrix', källa: 'Regressionen i Lika arbete'
                });
            }
        } catch (e) { rapporteraFel('Att göra: regressionen', e); }
    }

    // === 2. Prioriteringsanalysen (AKUT, åtgärd, bevaka) ===
    try {
        if (state.policy.length || state.statistik.length) {
            const ref = (typeof _selectedPrioReference === 'function')
                ? _selectedPrioReference()
                : (/** @type {HTMLInputElement} */ (document.querySelector('input[name="prio-ref"]:checked'))?.value || 'stallningstagande');
            const prioItems = (typeof computePrioritization === 'function') ? computePrioritization(ref) : [];
            prioItems.filter(i => i.status === 'akut').forEach(i => {
                const fmt = new Intl.NumberFormat('sv-SE');
                items.push({
                    id: `prio-akut-${i.aid || i.yrke}-${i.bas}`, aid: i.aid || null,
                    kategori: 'Värt att börja med',
                    prioritet: 'hög',
                    titel: `${i.yrke} (BAS ${i.bas}) — ${_agPct(i.diffPct)} % under ${i.refSource}`,
                    detalj: `n=${i.n}, kostnad att lyfta till referens: ${fmt.format(Math.round(i.annualGapTotal))} kr/år. Väg skillnaden mot sakliga skäl och dokumentera din bedömning.`,
                    tab: 'prioritering',
                    källa: 'Prioriteringsanalys'
                });
            });
            prioItems.filter(i => i.status === 'atgard').slice(0, 10).forEach(i => {
                items.push({
                    id: `prio-atgard-${i.aid || i.yrke}-${i.bas}`, aid: i.aid || null,
                    kategori: 'Värt att granska',
                    prioritet: 'medel',
                    titel: `${i.yrke} (BAS ${i.bas}) — ${_agPct(i.diffPct)} % under ${i.refSource}`,
                    detalj: `n=${i.n}, påverkansindex ${svTal(i.priorityIndex, 0)}. Titta närmare på om det finns sakliga skäl för skillnaden.`,
                    tab: 'prioritering',
                    källa: 'Prioriteringsanalys'
                });
            });
        }
    } catch (e) { rapporteraFel('Att göra: prioriteringen', e); }

    // === 3. § 3:10 Likvärdighetsanalys — kandidatpar ===
    // Paren kommer i första hand ur organisationens egna yrken; jämförelsestatistiken är
    // bara en reserv. Därför krävs ingen inläst statistik för att paren ska komma med.
    try {
        if (typeof computeLikvardighetPairs === 'function') {
            const lv = likvardighetResultat();
            // k-anonymitet: par med en grupp under tröskeln tas bort FÖRE begränsningen till 20
            // (undantaget gäller bara fliken Likvärdigt arbete); meningen om dem: _attGoraParNot().
            _parForRedovisning(lv?.pairs).par.slice(0, 20).forEach(p => {
                items.push({
                    id: `lv-${p.kvAid}-${p.maAid}-${p.kvBas}`, aid: p.kvAid || null,
                    kategori: 'Likvärdigt arbete',
                    prioritet: p.gapPct >= 10 ? 'hög' : 'medel',
                    titel: `${p.kvLabel || p.kvAid} (BAS ${p.kvBas}, ${svPct(p.kvKvinnoPct, 0)} kv) ligger ${_agPct(p.gapPct)} % under ${p.maLabel || p.maAid}`,
                    detalj: `Organisationens median ${Math.round(p.kvMedian).toLocaleString('sv-SE')} kr mot jämförelsestatistikens ${Math.round(p.maMedian).toLocaleString('sv-SE')} kr. Granska om kraven är likvärdiga och dokumentera sakliga skäl.`,
                    tab: 'likvardighet',
                    källa: 'Likvärdighetsanalys'
                });
            });
        }
    } catch (e) { rapporteraFel('Att göra: likvärdigt arbete', e); }

    if (!endastGrupper) {
        // === 4. EU-Lönekartläggning — per-BAS gap > 5 % efter korrigering för många tester (Benjamini–Hochberg) ===
        try {
            const reg = (typeof runOLSRegression === 'function') ? runOLSRegression() : null;
            if (reg && !reg.error && reg.perBas) {
                // BH-justering
                const okTests = reg.perBas.filter(p => p.status === 'ok' && isFinite(p.pValue));
                const bhQ = {};
                if (okTests.length > 1) {
                    const sorted = [...okTests].sort((a, b) => a.pValue - b.pValue);
                    const m = sorted.length;
                    const qRaw = sorted.map((t, i) => Math.min(1, t.pValue * m / (i + 1)));
                    for (let i = m - 2; i >= 0; i--) qRaw[i] = Math.min(qRaw[i], qRaw[i + 1]);
                    sorted.forEach((t, i) => { bhQ[t.bas] = qRaw[i]; });
                }
                reg.perBas.forEach(p => {
                    if (p.status !== 'ok') return;
                    const q = bhQ[p.bas];
                    const sig = p.pValue < 0.05 && (q == null || q < 0.05);
                    if (sig && Math.abs(p.gapPct) > 5) {
                        items.push({
                            id: `eu-bas-${p.bas}`,
                            kategori: 'EU 2023/970',
                            prioritet: 'hög',
                            titel: `BAS ${p.bas}: kvinnor ${_agPct(p.gapPct)} % ${_agRiktning(p.gapPct)} lön efter ålderskontroll — utredningskrav`,
                            detalj: `Statistiskt säkerställt också efter korrigering för många samtidiga tester (p=${p.pValue < 0.001 ? '< 0,001' : _agTal(p.pValue, 3)}, q=${q != null && q < 0.001 ? '< 0,001' : (q != null ? _agTal(q, 3) : '—')}). Över 5 %-tröskeln i EU:s lönetransparensdirektiv — här aktualiseras direktivets utredningssteg.`,
                            tab: 'matrix',
                            källa: 'Lika arbete'
                        });
                    }
                });
            }
        } catch (e) { rapporteraFel('Att göra: EU-direktivets mått', e); }

        // === 6. Livscykelanalys — växande gap ===
        try {
            const life = (typeof runLifecycleRegression === 'function') ? runLifecycleRegression(_lifecycleFixBas) : null;
            if (life && life.ok && life.gapDelta > 2 && (life.kvAgePVal < 0.10 || life.kvAge2PVal < 0.10)) {
                items.push({
                    id: 'livscykel-vaxer',
                    kategori: 'Livscykel',
                    prioritet: 'medel',
                    titel: `Lönegapet växer med åldern (+${_agTal(life.gapDelta, 1)} procentenheter mellan 25 och 65 år)`,
                    detalj: 'Kan indikera långsammare karriärväg för kvinnor, föräldraledighetseffekter eller könsbias i lönerevisioner. Granska lönerevisionshistorik och befordringsstatistik per kön.',
                    tab: 'kon',
                    källa: 'Livscykelanalys'
                });
            }
        } catch (e) { rapporteraFel('Att göra: livscykeln', e); }
    }

    return items;
}

// Länk till punktens flik. Datakvalitetspunkter hör till Översikt, där användaren
// redan är — de leder till Underlagets kvalitet i stället. aria-label skiljer
// länkarna åt för skärmläsare (annars heter alla "Gå dit").
function _attGoraLank(it, text, klass = '') {
    if (!it.tab) return '';
    const ankare = it.tab === 'dashboard' ? ' data-go-to-anchor="underlagets-kvalitet"' : '';
    // Namnet börjar med den synliga texten (WCAG 2.5.3), följd av punkten.
    return `<a href="#" data-go-to-tab="${esc(it.tab)}"${ankare} aria-label="${esc(text)}: ${esc(it.titel)}"${klass ? ` class="${klass}"` : ''}>${text}</a>`;
}

/** Meningen om § 3:10-par som utelämnats ur listan (grupp under tröskeln), annars tom sträng. */
function _attGoraParNot() {
    try {
        if (!state.data.length || typeof computeLikvardighetPairs !== 'function') return '';
        return _parForRedovisning(likvardighetResultat()?.pairs).not;
    } catch (_e) { return ''; }
}

/**
 * Renderar åtgärdslistan på Översikt. Visar grupperade kategorier, klickbara
 * checkboxar (state i minnet via state._actionChecklistDone-Set), CSV-export.
 */
function renderActionChecklist() {
    const wrap = document.getElementById('action-checklist-container');
    const kort = document.getElementById('att-gora');
    const borja = document.getElementById('att-gora-borja');
    if (!wrap) return;
    if (!state.data.length) { wrap.innerHTML = ''; if (kort) kort.hidden = true; if (borja) borja.innerHTML = ''; return; }
    if (kort) kort.hidden = false;

    const items = buildActionChecklist();
    // Hela listan är ett avsnitt som fälls ut: "Börja här" ovanför bär det som ska göras först.
    // Listan ritas om vid varje avbockning, så avsnittets läge bevaras.
    const varOppen = !!/** @type {HTMLDetailsElement} */ ((wrap.querySelector('#avsnitt-ov-punkter') || {})).open;
    const somAvsnitt = (nyckel, innehall) => `<details class="avsnitt" id="avsnitt-ov-punkter"${varOppen ? ' open' : ''}>
        <summary><span class="avsnitt-titel"><h2>Alla punkter</h2><span class="avsnitt-under">Hela listan, grupperad efter var punkten kommer ifrån</span></span><span class="avsnitt-nyckel" id="nyckel-ov-punkter">${esc(nyckel)}</span></summary>
        ${innehall}</details>`;
    const parNot = _attGoraParNot();
    const parNotHtml = parNot ? `<p class="att-gora-par-not text-dampad-sm marg-8-0-0 pad-0-4">${esc(parNot)}</p>` : '';
    if (!items.length) {
        wrap.innerHTML = somAvsnitt('Inga punkter', `<div class="insight-feed">
            <div class="insight-empty">Inga punkter att hantera. Verktyget har inte lyft något som sticker ut utifrån aktuell analys.</div>
            ${parNotHtml}
        </div>`);
        if (borja) borja.innerHTML = '<h3 class="att-gora-borja-rubrik">Börja här</h3><p>Inga punkter att hantera.</p>';
        return;
    }

    // Initiera klar-set om saknas
    if (!state._actionChecklistDone) state._actionChecklistDone = new Set();
    const done = state._actionChecklistDone;

    // Gruppera efter kategori
    const byKategori = {};
    items.forEach(it => {
        if (!byKategori[it.kategori]) byKategori[it.kategori] = [];
        byKategori[it.kategori].push(it);
    });

    // Prioriteten bär statusmärkena med egen form (03-ikoner.js): fylld cirkel för hög, triangel för medel — samma
    // märken som statusarna i tabellerna, så att färg aldrig är ensam om betydelsen.
    const prioKlass = p => p === 'hög' ? 'fg-kritisk' : p === 'medel' ? 'fg-varning' : 'fg-ok';
    const prioIcon  = p => p === 'hög' ? ikon('statusKritisk', 14) : p === 'medel' ? ikon('statusVarning', 14) : ikon('bock', 14);
    const totalDone = items.filter(it => done.has(it.id)).length;
    const totalCount = items.length;

    wrap.innerHTML = somAvsnitt(`${totalDone} av ${totalCount} hanterade`, `
        <div class="insight-feed">
            <div class="insight-feed-header rad-bryt-mitt mellan">
                <span class="avsnitt-verktyg-rubrik">Verktyg för listan</span>
                <div class="rad-mitt gap-10">
                    <span class="text-dampad-sm">${totalDone} / ${totalCount} hanterade</span>
                    <button id="btn-export-checklist" class="btn btn-secondary btn-sm" title="Exportera som CSV — öppnas direkt i Excel/Word">CSV</button>
                    <button id="btn-checklist-clear-done" class="btn btn-secondary btn-sm" title="Avmarkera alla för att börja om">Rensa markeringar</button>
                </div>
            </div>
            <p class="text-dampad-sm lh-1_55 marg-8-0-14 pad-0-4">
                Sammanställning av alla punkter du behöver hantera enligt verktygets analyser.
                Klicka på rutorna när du hanterat punkten. Exportera som CSV för att klistra in
                i Word-mallen eller dela med ansvariga kollegor. Markeringarna sparas under sessionen
                men försvinner när du stänger fliken (GDPR — ingen persistens).
            </p>
            ${parNotHtml}
            ${Object.entries(byKategori).map(([kat, list]) => `
                <details open class="ag-grupp">
                    <summary>
                        ${esc(kat)} <span class="text-dampad-sm fw-normal">(${list.length} punkt${list.length === 1 ? '' : 'er'}, ${list.filter(it => done.has(it.id)).length} hanterade)</span>
                    </summary>
                    <ul class="utan-punkter marg-0 pad-0">
                        ${list.map(it => `
                            <li class="topp ram-t-1-kant rad gap-12 pad-10-14${done.has(it.id) ? ' bg-ok-yta' : ''}">
                                <input type="checkbox" class="act-cb pekare marg-t-3" data-id="${esc(it.id)}" ${done.has(it.id) ? 'checked' : ''} aria-label="Markera som hanterad: ${esc(it.titel)}">
                                <div class="flex-1">
                                    <div class="rad-bryt baslinje gap-8">
                                        <span class="ag-prio ${prioKlass(it.prioritet)}">${prioIcon(it.prioritet)} ${esc(it.prioritet.charAt(0).toUpperCase() + it.prioritet.slice(1))}</span>
                                        <strong class="fs-md${done.has(it.id) ? ' farg-dampad genomstruken' : ''}">${esc(it.titel)}</strong>
                                    </div>
                                    <div class="text-dampad-sm lh-1_5 marg-t-4">${esc(it.detalj)}</div>
                                    <div class="finstilt">
                                        Källa: ${esc(it.källa)} ·
                                        ${_attGoraLank(it, 'öppna fliken', 'farg-primary utan-understrykning')}
                                    </div>
                                </div>
                            </li>`).join('')}
                    </ul>
                </details>`).join('')}
        </div>
    `);

    const oppna = _agBorjaHar(items, done);   // ordningen: src/lib/attgora.js (ADR-29)
    if (borja) borja.innerHTML = `<h3 class="att-gora-borja-rubrik">Börja här</h3>` + (oppna.length
        ? `<ol class="att-gora-borja-lista">${oppna.map(it => `<li data-borja-id="${esc(it.id)}"><strong>${esc(it.titel)}</strong> <span class="att-gora-kat">${esc(it.kategori)}</span>${it.tab ? ' ' + _attGoraLank(it, 'Gå dit') : ''}</li>`).join('')}</ol>`
        : '<p>Alla punkter är hanterade.</p>');

    // Checkbox-handlers
    wrap.querySelectorAll('.act-cb').forEach(cb => {
        cb.addEventListener('change', () => {
            const id = /** @type {HTMLElement} */ (cb).dataset.id || '';
            if (/** @type {HTMLInputElement} */ (cb).checked) done.add(id);
            else done.delete(id);
            renderActionChecklist();  // omrendrera för uppdaterad räknare + bakgrundsfärg
        });
    });

    // CSV-export
    document.getElementById('btn-export-checklist')?.addEventListener('click', () => medExportLage(() => exportActionChecklistCSV(buildActionChecklist(), done)));

    // Rensa markeringar
    document.getElementById('btn-checklist-clear-done')?.addEventListener('click', () => {
        if (!confirm('Avmarkera alla ' + done.size + ' hanterade punkter?')) return;
        state._actionChecklistDone = new Set();
        renderActionChecklist();
    });
}

/**
 * Exporterar åtgärdslistan som CSV.
 */
// Går alltid genom exportläget (ADR-51): djupräknaren håller skärmen i exportläget tills den sista pågående exporten är klar.
function exportActionChecklistCSV(...a) { return medExportLage(() => _exportActionChecklistCSVExport.apply(null, /** @type {any} */ (a))); }
function _exportActionChecklistCSVExport(items, done) {
    if (!items.length) { alert('Ingen åtgärdslista att exportera.'); return; }
    const rows = [[
        'Status', 'Prioritet', 'Kategori', 'Punkt', 'Detalj', 'Källa', 'Flik'
    ]];
    items.forEach(it => {
        rows.push([
            done.has(it.id) ? 'Hanterad' : 'Öppen',
            it.prioritet.toUpperCase(),
            it.kategori,
            it.titel,
            it.detalj,
            it.källa,
            it.tab
        ]);
    });
    rows.push([]);
    rows.push(['# METADATA']);
    rows.push(['Genererad', new Date().toLocaleString('sv-SE')]);
    rows.push(['Verktyg', 'Öppen lönekartläggning v' + (typeof APP_VERSION !== 'undefined' ? APP_VERSION : '–')]);
    rows.push(['Totalt punkter', items.length]);
    rows.push(['Hanterade', items.filter(it => done.has(it.id)).length]);
    const parNot = _attGoraParNot();
    if (parNot) rows.push(['Utelämnade par', parNot]);
    _downloadCSV(rows, 'atgardslista_' + new Date().toISOString().slice(0, 10));
}
