// ============================================================
// #8 Reproducerbarhets-appendix — identiska metod- och parameteruppgifter i
// ALLA exporter, så varje flaggat resultat går att återskapa och försvara i
// samverkan/tvist. Två format: aoa-rader (Excel) och HTML (print/rapport).
// ============================================================
function _methodAppendixData() {
    const total = (state.data && state.data.length) || 0;
    const used  = (typeof getData === 'function' ? getData().length : total);
    const ver   = (typeof APP_VERSION !== 'undefined' ? APP_VERSION : '–');
    return [
        ['Verktyg', `Öppen lönekartläggning (v${ver})`],
        ['Exporttidpunkt', new Date().toLocaleString('sv-SE')],
        ['Artefakt-SHA-256', 'Se RELEASE.txt / filens banner (single-file-bygget är källans sanning)'],
        ['Datakälla', state.isDemo
            ? '⚠ DEMODATA — syntetisk exempeldata, INTE en verklig analys'
            : 'Lokalt uppladdad fil (bearbetad helt i webbläsaren, inga nätverksanrop)'],
        ['Antal personer (inläst)', String(total)],
        ['Antal personer (i denna analys)', String(used)],
        ['Nationell referens för andel kvinnor', skrForklaring()],
        ['Modell — oförklarat gap', 'OLS på log(månadslön) ~ kön + ålder + BAS-intervall (indikatorvariabler, första BAS som referens); HC3-robusta standardfel (Long & Ervin 2000)'],
        ['Steg + Yrkesgrupp (dekomponeringen)', 'Könsgap med fasta effekter för yrkesgrupp inom BAS (AID×BAS) utöver ålder, skattat med inomtransformation; visas som sista steg, ingår inte i huvudtalet'],
        ['Ålder & karriär (tvärsnitt)', 'Lön mot ålder och livscykelmodellen bygger på ett tvärsnitt: de visar skillnader mellan åldersgrupper i dag, inte hur en persons lön utvecklas över karriären (kohorteffekter)'],
        ['Trattdiagrammet', 'Med färre än tio yrkesgrupper säger trattens form lite; varje grupp bedöms då för sig i tabellen. Punktens bedömning bygger på en omkastning av könen inom gruppen'],
        ['p-värden', 't-fördelning vid df < 100, annars normalfördelning; Benjamini-Hochberg (FDR) vid multipla grupptest'],
        ['Konfidensintervall', 'Bootstrap-percentil (B ≥ 1000 sampel) på mediankvot kvinna/man'],
        ['Signifikansnivå', 'α = 0,05'],
        ['Minsta gruppstorlek för redovisning', `${kInstalld()} personer. Grupper med färre redovisas inte i det som lämnar verktyget (gäller inte likvärdighetsanalysen); på skärmen visas alla grupper.`
            + (kInstalld() < K_STANDARD ? ` Tröskeln är sänkt från standardvärdet ${K_STANDARD}.` : '')],
        ['Referens för lönenivåer', referensNamn() + referensKalla()],
        ['Jämförelsestatistik', statistikBeskrivning()],
        ['Krav-proxy (likvärdigt arbete)', state.arbetsvardering ? 'Arbetsvärderingspoäng (ur strukturdatans Poäng-kolumn)' : 'BAS-intervall (ordinal rangordning)'],
        ['Lönegapets tecken', 'Verktyget räknar skillnaden som (kvinnor − män) / män och visar den som kvinnors lön i procent av mäns (under 100 = kvinnor lägre). EU-lönerapporten och rapportens avsnitt om lönetransparens redovisar i stället direktivets lönegap, (män − kvinnor) / män i procent, enligt art. 9: positivt tal = kvinnor lägre. Beloppet är detsamma.'],
        ['Tolkningsregel', 'Ett oförklarat gap är en statistisk signal om var man bör titta närmare — inte ett bevis för osaklig (diskriminerande) löneskillnad. Den bedömningen görs kvalitativt av arbetsgivaren.'],
        ['Rättslig ram', 'Diskrimineringslagen 3 kap. (lönekartläggning); direktiv (EU) 2023/970 om lönetransparens. De enskilda lagrummen står i docs/utveckling/lagrum.md.']
    ];
}
// Lägger till ett "Metod & parametrar"-blad sist i en XLSX-arbetsbok.
// `undantag`: exporten hör till ett dokumenterat undantag från minsta gruppstorlek och säger det.
// `extra`: rader [rubrik, text] som bara gäller den här arbetsboken (ett blads mått och regler); läggs sist.
/**
 * @param {any} wb
 * @param {{undantag?: string, extra?: any[][]}} [val]
 */
function _appendMethodSheet(wb, { undantag = '', extra = [] } = {}) {
    if (typeof XLSX === 'undefined' || !XLSX.utils || !wb) return;
    const rows = [['Metod & parametrar — reproducerbarhet och tolkning'], [''], ...(_methodAppendixData()), ...extra];
    if (undantag) {
        const i = rows.findIndex(r => r[0] === 'Minsta gruppstorlek för redovisning');
        rows.splice(i + 1, 0, ['Undantag från minsta gruppstorlek', _kUndantagNot(undantag)]);
    }
    const ws = XLSX.utils.aoa_to_sheet(rows);
    ws['!cols'] = [{ wch: 32 }, { wch: 88 }];
    try { XLSX.utils.book_append_sheet(wb, ws, 'Metod & parametrar'); } catch (_e) { /* dubblettnamn: hoppa */ }
}
// ---- Excel-export-hjälpare: rensar HTML-tabell för läsbara Excel-celler ----
/**
 * Klonar en HTML-tabell och rensar bort UI-element som inte hör hemma i Excel:
 *   - informationsikonerna (.info-tip)
 *   - status-badges (⚠ ⚠ 🔒 ✓ ✕ etc.)
 *   - knappar (cross-links, förslag-knappar)
 *   - checkboxar konverteras till "Ja"/"Nej"
 *
 * Headers kan överrides via `data-export-label` på <th>:
 *   <th data-export-label="Median organisationen (kr/mån)">Median</th>
 *
 * Kolumner kan exkluderas helt via `data-export-skip` på <th>.
 *
 * @param {string} tableId
 * @returns {HTMLTableElement | null} Klonad tabell redo för XLSX-konvertering
 */
/**
 * En hopfälld grupp, en rad som en sökning gömt eller en hopfälld underrad är fortfarande en del av tabellen: i en
 * export (arbetsboken, PDF-rapportens bilaga) är alla rader synliga. Görs på en kopia, aldrig på skärmens tabell.
 */
function _exportVisaAllaRader(klon) {
    klon.querySelectorAll('tbody tr').forEach(tr => {
        tr.style.removeProperty('display');
        if (!tr.getAttribute('style')) tr.removeAttribute('style');   // ett tomt style="" i markeringen räknas som överträdelse av CSP:n (style-src-attr 'none') när raden sätts in i PDF-rapporten
        tr.hidden = false;
        tr.classList.remove('collapsed');
    });
    return klon;
}
// Går alltid genom exportläget (ADR-51): djupräknaren håller skärmen i exportläget tills den sista pågående exporten är klar.
function _cloneAndCleanTableForExport(...a) { return medExportLage(() => __cloneAndCleanTableForExportExport.apply(null, /** @type {any} */ (a))); }
function __cloneAndCleanTableForExportExport(tableId) {
    // Exportläget (ADR-51): tabellen läses med den inställda tröskeln, också när anroparen inte gått in i läget.
    const t = exportElement(tableId);   // exportgrinden: tabellens flik är ritad med det som gäller nu
    if (!t || !t.querySelector('tbody tr')) return null;
    const clone = t.cloneNode(true);
    _exportText(clone);
    _exportVisaAllaRader(clone);

    // Identifiera kolumnindex att skippa
    const skipCols = [];
    const ths = /** @type {HTMLElement} */ (clone).querySelectorAll('thead th');
    ths.forEach((th, i) => {
        if (th.hasAttribute('data-export-skip')) skipCols.push(i);
    });

    // Rensa header-celler
    ths.forEach(th => {
        const exportLabel = th.getAttribute('data-export-label');
        if (exportLabel) {
            th.textContent = exportLabel;
            return;
        }
        // Ta bort info-tip spans, badges, sr-only-text
        th.querySelectorAll('.info-tip, .sr-only, sup').forEach(el => el.remove());
        // Normalisera whitespace
        th.textContent = th.textContent.replace(/\s+/g, ' ').trim();
    });

    // Rensa data-celler från knappar, badges etc.
    /** @type {HTMLElement} */ (clone).querySelectorAll('tbody tr').forEach(tr => {
        // Konvertera checkboxar till "Ja"/"Nej"
        tr.querySelectorAll('input[type="checkbox"]').forEach(cb => {
            const td = cb.closest('td');
            if (td) td.textContent = /** @type {HTMLInputElement} */ (cb).checked ? 'Ja' : 'Nej';
        });
        // Ta bort knappar (cross-link, suggest; brist-toggle är redan gjord till text ovan)
        tr.querySelectorAll('.row-cross-link, .btn-suggest, button, input[type="text"]').forEach(el => el.remove());
        // Strippa kvarvarande icon-suffix från cell-text (⚠ ⚠ 🔒 ✓ ✕ 🔴 ⛔ etc.)
        tr.querySelectorAll('td, th').forEach(td => {
            // Behåll text-noden men ta bort ikon-spans (cursor:help-badges etc.)
            td.querySelectorAll('span[title].hjalp-markor').forEach(s => s.remove());
            // Normalisera whitespace inom cellen
            // Staplarnas mått ligger som style-attribut (satta via CSSOM); sätts markeringen om genom innerHTML blockerar CSP:n dem
            // (style-src-attr 'none'), och exporten behöver dem inte.
            td.querySelectorAll('[style]').forEach(el => el.removeAttribute('style'));
            td.innerHTML = td.innerHTML.replace(/&nbsp;/g, ' ');
        });
        // Varje cell får sin typ bestämd här, inte av kalkylbladsläsarens gissning (ADR-30/43: tabellen är det
        // som visas, arbetsboken ska bära samma sak). Se _exportCellVarde: ett tal i cellens text blir ett tal med
        // sin enhet som talformat, allt annat blir text — också "17/17", som läsaren annars tolkar som ett datum.
        tr.querySelectorAll('td, th').forEach(td => _exportMarkCell(td));
    });

    // Skippa kolumner via DOM-manipulation. Kolumnindex räknas i tabellens logiska kolumner: en cell med colspan
    // täcker flera, så en rad med en sammanslagen cell har färre barn än rubrikraden (notrader, "Gruppens median").
    if (skipCols.length) {
        ['thead tr', 'tbody tr', 'tfoot tr'].forEach(sel => {
            /** @type {HTMLElement} */ (clone).querySelectorAll(sel).forEach(tr => {
                let kol = 0;
                [...tr.children].forEach(cell => {
                    const span = Math.max(1, parseInt(cell.getAttribute('colspan') || '', 10) || 1);
                    const start = kol, slut = kol + span - 1;
                    kol += span;
                    const traffar = skipCols.filter(i => i >= start && i <= slut).length;
                    if (!traffar) return;
                    if (traffar >= span) cell.remove();
                    else cell.setAttribute('colspan', String(span - traffar));
                });
            });
        });
    }

    return clone;
}

/**
 * Ett tal i svenskt visningsformat, med enhet: "32 067 kr" → { tal: 32067, enhet: 'kr', dec: 0 },
 * "−4,45 %" → { tal: -4.45, enhet: '%', dec: 2 }, "1,30" → { tal: 1.3, enhet: '', dec: 2 }. Null när texten
 * är något annat än ett ensamt tal ("17/17", "46 (28/18)", "Gruppens median 29 985 kr", "–").
 */
function _exportTalMedEnhet(text) {
    const t = String(text == null ? '' : text).replace(/[  ]/g, ' ').replace(/\s+/g, ' ').trim();
    const m = /^([+−-]?)(\d{1,3}(?: \d{3})+|\d+)(?:,(\d+))? ?(%|kr)?$/.exec(t);
    if (!m) return null;
    const tecken = m[1] === '−' ? '-' : m[1];
    const tal = parseFloat(tecken + m[2].replace(/ /g, '') + (m[3] != null ? '.' + m[3] : ''));
    if (!isFinite(tal)) return null;
    return { tal, enhet: m[4] || '', dec: m[3] != null ? m[3].length : 0 };
}

/**
 * Cellens värde i arbetsboken, ur det cellen VISAR.
 *
 *  - Texten är ett tal ("93,6 %", "33 932 kr", "46"): talet, i procent när enheten är procent (93.6, inte 0.936),
 *    med enheten som talformat. data-sort-value tas bara när det är samma storhet med fler decimaler (33 931,5
 *    bakom "33 932 kr") — inte när det är något annat än det som visas (gapet 6,4 bakom kvoten "93,6 %", andelen
 *    −0,0445 bakom "−4,45 %", prioriteringsindexet bakom statustexten).
 *  - Annars texten som text — "17/17" skulle läsaren annars göra till ett datum, "46 (28/18)" och "–" till ingenting.
 *
 * @returns {{t:'n', v:number, z?:string}|{t:'s', v:string}|null} null för en tom cell.
 */
/**
 * @param {HTMLTableCellElement} td
 * @returns {{t: 'n'|'s', v: any, z?: string}|null}
 */
function _exportCellVarde(td) {
    const text = td.textContent.replace(/[  ]/g, ' ').replace(/\s+/g, ' ').trim();
    if (text === '') return null;
    const p = _exportTalMedEnhet(text);
    if (!p) return { t: 's', v: text };
    let v = p.tal;
    const sv = td.getAttribute && td.getAttribute('data-sort-value');
    if (sv != null && sv.trim() !== '') {
        const n = parseFloat(sv);
        if (isFinite(n) && Math.abs(n - p.tal) <= 0.5 * Math.pow(10, -p.dec) + 1e-9) v = n;
    }
    const dec = p.dec ? '.' + '0'.repeat(p.dec) : '';
    const z = p.enhet === '%' ? `0${dec}\\ "%"` : p.enhet === 'kr' ? '#,##0\\ "kr"' : p.dec ? `0${dec}` : null;
    return z ? { t: 'n', v, z } : { t: 'n', v };
}

/** Skriver cellens värde i attributen data-t/data-v/data-z, som table_to_sheet läser utan att gissa, och i texten. */
function _exportMarkCell(td) {
    const c = _exportCellVarde(td);
    if (!c) return;
    td.setAttribute('data-t', c.t);
    td.setAttribute('data-v', String(c.v));
    if (c.z) td.setAttribute('data-z', c.z);
    td.textContent = String(c.v);
}

/** Standard-format-map för svenska användare. Triggas av nyckelord i kolumnrubriken. */
const SV_NUM_FORMATS = Object.freeze({
    // Ordningen avgör: första träffen gäller. Rubriker som "Kvinnors median i % av männens", "P10 skillnad mot …
    // (%)" och "Avvikelse per person (kr/mån)" innehåller flera nyckelord, så enheten i parentesen prövas först.
    '(%)':      '0.00\\ "%"',
    ' % av':    '0.0\\ "%"',
    'kr/mån':   '#,##0\\ "kr"',
    '(kr':      '#,##0\\ "kr"',
    ' kr)':     '#,##0\\ "kr"',
    '(kvot)':   '0.00',
    'avvikelse': '0.00\\ "%"',     // anv "Avvikelse %"
    'gap':      '0.00\\ "%"',
    'diff (%)': '0.00\\ "%"',
    'diff mot': '0.00\\ "%"',
    'andel':    '0.0\\ "%"',
    'lön':      '#,##0\\ "kr"',
    'median':   '#,##0\\ "kr"',
    'kostnad':  '#,##0\\ "kr"',
    'referens': '#,##0\\ "kr"',
    'antal':    '#,##0',
    'index':    '0',
    'ålder':    '0'
});

/**
 * Bygger AOA-block av en rensad tabellklon med grupprader (tr.group-header):
 *
 *   BAS A                    ← grupptitel (egen rad)
 *   Yrke | P10 | Median | …  ← kolumnrubriker (UPPREPAS per grupp)
 *   datarad…
 *   (tomrad)                 ← skiljer blocken åt
 *   BAS B
 *   Yrke | P10 | Median | …
 *   …
 *
 * Syfte: HR ska kunna markera ett blocks rubrikrad + datarader i Excel och
 * klistra in direkt i Word som en ren tabell per BAS — i stället för dagens
 * enda långa tabell där grupptiteln blir en encellsrad mitt i datat.
 * Tal hämtas från data-sort-value (riktiga numbers → svenska talformat).
 *
 * @param {HTMLTableElement} clone - Från _cloneAndCleanTableForExport.
 * @returns {{aoa:Array<Array>, merges:Array, firstHeaderRowIdx:number|null}}
 */
function _groupedCloneToAoa(clone) {
    const headers = [...clone.querySelectorAll('thead th')]
        .map(th => th.textContent.replace(/\s+/g, ' ').trim());
    const aoa = [];
    const merges = [];
    /** @type {number|null} */ let firstHeaderRowIdx = null;
    const cellValue = td => {
        // Cleanern (_exportMarkCell) har redan bestämt typ, värde och talformat; ett tal blir ett cellobjekt.
        const t = td.getAttribute && td.getAttribute('data-t');
        if (t === 'n') {
            const cell = { t: 'n', v: parseFloat(td.getAttribute('data-v')) };
            const z = td.getAttribute('data-z');
            if (z) cell.z = z;
            return cell;
        }
        return td.textContent.replace(/\s+/g, ' ').trim();
    };
    [...clone.querySelectorAll('tbody tr')].forEach(tr => {
        if (tr.classList.contains('group-header')) {
            if (aoa.length) aoa.push([]);   // tomrad mellan block
            const title = tr.textContent.replace(/\s+/g, ' ').trim();
            merges.push({ s: { r: aoa.length, c: 0 }, e: { r: aoa.length, c: Math.max(0, headers.length - 1) } });
            aoa.push([title]);
            if (firstHeaderRowIdx === null) firstHeaderRowIdx = aoa.length;
            aoa.push(headers.slice());
        } else {
            aoa.push([...tr.children].map(cellValue));
        }
    });
    return { aoa, merges, firstHeaderRowIdx };
}

/**
 * Sätter kolumnbredder (!cols) utifrån längsta innehåll per kolumn, 8–45 tecken
 * — så exporten är läsbar direkt utan manuell breddjustering i Excel.
 * @param {Object} sheet - XLSX worksheet.
 */
function _autoColWidths(sheet) {
    if (!sheet || !sheet['!ref']) return;
    const range = XLSX.utils.decode_range(sheet['!ref']);
    const widths = [];
    for (let c = range.s.c; c <= range.e.c; c++) {
        let max = 8;
        for (let r = range.s.r; r <= range.e.r; r++) {
            const cell = sheet[XLSX.utils.encode_cell({ c, r })];
            if (!cell || cell.v == null) continue;
            const len = String(cell.v).length + (cell.t === 'n' ? 4 : 0); // marginal för "kr"/"%"-format
            if (len > max) max = len;
        }
        widths.push({ wch: Math.min(45, max + 1) });
    }
    sheet['!cols'] = widths;
}

/** Klonar+rensar och returnerar XLSX-worksheet. Tillämpar svenska number-format.
 *  BAS-grupperade tabeller (tr.group-header) exporteras som Word-vänliga block
 *  med upprepade kolumnrubriker per grupp (se _groupedCloneToAoa). */
function tableToCleanSheet(tableId) {
    const clone = _cloneAndCleanTableForExport(tableId);
    if (!clone) return null;
    if (/** @type {HTMLElement} */ (clone).querySelector('tbody tr.group-header')) {
        const g = _groupedCloneToAoa(/** @type {HTMLTableElement} */ (clone));
        const sheet = XLSX.utils.aoa_to_sheet(g.aoa);
        if (g.merges.length) sheet['!merges'] = g.merges;
        _applyColumnNumFormats(sheet, SV_NUM_FORMATS, g.firstHeaderRowIdx ?? 0);
        _autoColWidths(sheet);
        // Ingen frusen rad — rubrikerna upprepas per block i stället.
        return sheet;
    }
    const sheet = XLSX.utils.table_to_sheet(clone);
    _applyColumnNumFormats(sheet, SV_NUM_FORMATS);
    _autoColWidths(sheet);
    // Frys första raden (header) för läsbarhet
    sheet['!freeze'] = { ySplit: 1 };
    return sheet;
}

/**
 * Tillämpar Excel-cellsformat (z-property) på alla data-rader för kolumner
 * vars header matchar en av nyckel-substrings. Excel använder sedan
 * användarens locale för faktisk rendering — "#,##0" blir "1 234" i svenska
 * Excel, "1,234" i engelska.
 *
 * Exempel:
 *   _applyColumnNumFormats(sheet, {
 *       'kr':   '#,##0\\ "kr"',       // 32 067 kr
 *       '%':    '0.0\\ "%"',          // -12.3 %
 *       'n':    '#,##0',              // 1 234
 *       'år':   '0'                   // 45
 *   });
 *
 * @param {Object} sheet  - XLSX worksheet
 * @param {Object} formatMap - { kolumnsubstring: formatString }
 * @param {number} [headerRowIdx=0] - vilken rad är headern (0-indexerad)
 */
function _applyColumnNumFormats(sheet, formatMap, headerRowIdx = 0) {
    if (!sheet || !sheet['!ref']) return;
    const range = XLSX.utils.decode_range(sheet['!ref']);
    for (let c = range.s.c; c <= range.e.c; c++) {
        const headerAddr = XLSX.utils.encode_cell({ c, r: range.s.r + headerRowIdx });
        const headerCell = sheet[headerAddr];
        if (!headerCell || typeof headerCell.v !== 'string') continue;
        const headerLow = headerCell.v.toLowerCase();
        for (const [pattern, fmt] of Object.entries(formatMap)) {
            if (headerLow.includes(pattern.toLowerCase())) {
                for (let r = range.s.r + headerRowIdx + 1; r <= range.e.r; r++) {
                    const addr = XLSX.utils.encode_cell({ c, r });
                    const cell = sheet[addr];
                    if (cell && cell.t === 'n' && !cell.z) cell.z = fmt;
                }
                break;  // använd första matchande pattern, hoppa till nästa kolumn
            }
        }
    }
}

/** Klonar+rensar och returnerar XLSX-workbook (för en-flik-export).
 *  Delegerar till tableToCleanSheet så BAS-grupperade tabeller får samma
 *  Word-vänliga blockformat i alla exportvägar. */
function tableToCleanBook(tableId, sheetName) {
    const sheet = tableToCleanSheet(tableId);
    if (!sheet) return null;
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, sheet, sheetName);
    return wb;
}

// ---- Excel export-varning (GDPR-affordans) ----
/**
 * Visar en kort, icke-blockerande "post-export"-notis så HR påminns om att
 * aggregerade lönefiler är känsliga och inte ska mailas okrypterat.
 * Vi blockerar inte exporten — vi gör organisatorisk-känsligheten synlig.
 */

// ---- CSV-export --------------------------------------------------------------
// Robust CSV-helper som INTE är beroende av XLSX-biblioteket. Producerar
// semikolon-separerade filer med UTF-8 BOM (svenska Excel-default), CRLF-
// radslut och korrekta citerade fält. Garanterat fungerande i alla webbläsare:
// blob-URL + anchor-klick + revokeObjectURL.
// En textcell som börjar med = + - @ (eller tabb/CR) blir en formel när filen
// öppnas eller klistras in i Excel. Yrkesnamn och andra texter kommer ur lönefilen,
// så en fientlig fil kunde annars lägga en formel i HR:s export (CSV-injektion,
// OWASP). Sådana celler får ett inledande apostrof-tecken, som Excel visar som
// text. Tal — även formaterade som "-3,2 %" eller "-1 250 kr" — lämnas orörda.
const _CSV_FORMELSTART = /^[=+\-@\t\r]/;
const _CSV_TALLIKT = /^[+-]?\d[\d\s.,]*(\s?(%|kr|st|år))?$/;
function _neutraliseraCell(v) {
    if (typeof v !== 'string' || !_CSV_FORMELSTART.test(v) || _CSV_TALLIKT.test(v)) return v;
    return "'" + v;
}

function _toCsv(rows, delimiter) {
    delimiter = delimiter || ';';
    const escapeCell = v => {
        if (v == null) return '';
        let s = String(_neutraliseraCell(v));
        if (s.includes(delimiter) || s.includes('"') || s.includes('\n') || s.includes('\r')) {
            s = '"' + s.replace(/"/g, '""') + '"';
        }
        return s;
    };
    return rows.map(r => (Array.isArray(r) ? r : [r]).map(escapeCell).join(delimiter)).join('\r\n');
}
// Demoläget märks i filnamnet, som diagram- och Word-exporterna (bara en gång).
function _csvFilnamn(namn) {
    const n = namn || 'export';
    return state.isDemo && !n.startsWith('DEMO_') ? 'DEMO_' + n : n;
}
// `undantag`: se _kUndantagNot (06) — exporten kan innehålla grupper under tröskeln och säger det.
function _downloadCSV(rows, filename, { undantag = '' } = {}) {
    if (!Array.isArray(rows) || !rows.length) {
        alert('Ingen data att exportera.');
        return;
    }
    try {
        const BOM = '﻿';  // UTF-8 BOM så Excel öppnar med korrekt teckenkodning
        const csv = BOM + _toCsv(_csvMedStampel(rows, undantag));
        const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = _csvFilnamn(filename) + '.csv';
        a.style.display = 'none';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        setTimeout(() => URL.revokeObjectURL(url), 1500);
        if (typeof _showExportSensitivityToast === 'function') _showExportSensitivityToast();
        if (typeof announceToScreenReader === 'function') announceToScreenReader('CSV exporterad: ' + (rows.length - 1) + ' rader.');
    } catch (err) {
        alert('CSV-export misslyckades: ' + (err.message || String(err)));
    }
}

function _showExportSensitivityToast(bodyHtml) {
    const existing = document.getElementById('export-sensitivity-toast');
    if (existing) existing.remove();
    const toast = document.createElement('div');
    toast.id = 'export-sensitivity-toast';
    toast.setAttribute('role', 'status');
    toast.style.cssText = `position:fixed; bottom:24px; right:24px; max-width:380px; padding:14px 18px; background:${FARG.text}; color:${FARG.yta}; border-left:4px solid ${FARG.varning}; border-radius:8px; box-shadow:0 6px 20px rgba(0,0,0,0.28); z-index:99998; font-size:0.88rem; line-height:1.55;`;
    // Neutral text: notisen visas efter alla exporter, också de som innehåller en rad per person
    // eller grupper under tröskeln, och ska därför inte utlova aggregering.
    const body = bodyHtml || `<strong>Fil sparad</strong><br>
        Filen innehåller lönedata. Hantera den som personuppgifter: förvara den på behörighetsstyrd disk och skicka den inte via okrypterad e-post.`;
    toast.innerHTML = body
        + `<button data-dismiss-parent class="bak-transparent ram-1-blek rund-4 farg-yta pekare fs-xs marg-v-8 marg-t-6 pad-2-10">OK</button>`;
    // Markeringsraden ligger också nere till höger: notisen ställs ovanför den, så att ingen täcker den andra.
    if (document.getElementById('markering-rad')) toast.style.bottom = '76px';
    document.body.appendChild(toast);
    setTimeout(() => { if (toast.parentNode) toast.remove(); }, 12000);
}

// ---- Multi-flik Excel-export ----
// SPDX-License-Identifier: MIT
// Copyright 2026 Felix Jansson
// ====================================================================
// 23-exportgrind.js — Exportgrinden (ADR-40)
//
// Flera exporter läser tabeller och diagram ur sidan. När minsta gruppstorlek ändras ritas en flik om först när
// den öppnas, och grinden här ser till att ingen export kan läsa ur en flik som inte är ritad med det som gäller nu.
//
// Två saker tillsammans:
//  1. När tröskeln ändras TÖMS varje flik som inte syns (tomFlikarUtom): tabellkroppar, diagram och flikens topp.
//     En flik som inte syns bär alltså aldrig tal från en tröskel som inte längre gäller, hur den än ritades.
//  2. En räknare (generationen) ökar vid samma tillfälle, och varje flik minns vid vilken generation
//     renderTabContent senast ritade den. De två funktioner som ALL export av tabeller respektive diagram går genom
//     (_cloneAndCleanTableForExport och _chartExportUnderlag) frågar grinden först: en flik som ritades före
//     ändringen ritas om innan något läses ur den. Går det inte, exporteras ingenting ur den — hellre en utebliven
//     export än en med fel tröskel.
// tests/ktroskel.test.js prövar varje exportväg mot detta.
// ====================================================================
// ---- Exportläget (ADR-51) ----
// På skärmen maskeras inget (kTroskel() är 1). Allt som lämnar verktyget ritas och räknas i exportläget, där
// kTroskel() är den inställda tröskeln. Ett byte av läge är som en ändrad tröskel: generationen ökar, så att
// grinden ritar om varje flik som läses, och efteråt ritas skärmen tillbaka. De två funktioner all export av
// tabeller och diagram går genom (_cloneAndCleanTableForExport, _chartExportUnderlag) går själva in i
// exportläget om anroparen inte redan gjort det, så ingen väg kan läsa skärmens omaskade tal.
function iExportLage() { return state.kLage === 'export'; }
function _bytKLage(lage) {
    state.kLage = lage;
    ritGenerationNy();                                                      // allt som är ritat bär det andra läget
    // Bara det som räknas med kTroskel() släpps: Lika arbetes minne och livscykelns. Skattningarna (statGolv,
    // bootstrap, styrka, § 3:10-paren) är desamma i båda lägena och behålls.
    state._lifecycleCache = null;
    if (typeof laMinneSlapp === 'function') laMinneSlapp();
}
/**
 * Ritar skärmen tillbaka efter en export: Översikts delar och den öppna fliken (som grinden kan ha ritat i
 * exportläget), utom Dokumentera & exportera, som alltid ritas i exportläget. Flikar som inte syns töms inte: det
 * de bär är ritat med den inställda tröskeln (försiktigare än skärmen), och de ritas om när de öppnas.
 */
function _ritaOmEfterExport() {
    if (!state.data.length || typeof _omritningssteg !== 'function') return;
    for (const [namn, fn] of _omritningssteg()) { if (namn === 'dokumentera' || namn === 'flikar som inte syns') continue; _omritningForsok(namn, fn); }
}
/**
 * Kör fn i exportläget och går tillbaka till skärmläget efteråt (också när fn ger ett löfte eller kastar).
 * Nästlade anrop byter inte läge. Fn:s värde returneras.
 * @template T
 * @param {() => T} fn
 * @returns {T}
 */
let _exportDjup = 0;   // pågående exporter (nästlade eller överlappande i tid): skärmen ritas tillbaka när den sista är klar
function medExportLage(fn) {
    // Den yttersta exporten byter läge och ritar tillbaka; ett läge som satts utifrån (state.kLage = 'export') rörs inte.
    const yttre = _exportDjup === 0 && !iExportLage();
    if (yttre) _bytKLage('export');
    _exportDjup++;
    let synk = true;
    const tillbaka = () => { _exportDjup = Math.max(0, _exportDjup - 1); if (_exportDjup === 0 && yttre) { _bytKLage('skarm'); _ritaOmEfterExport(); } };
    try {
        const r = fn();
        if (r && typeof /** @type {any} */ (r).then === 'function') { synk = false; return /** @type {any} */ (r).finally(tillbaka); }
        return r;
    } finally { if (synk) tillbaka(); }
}

let _ritGeneration = 1;
const _ritadVid = new Map();     // flik → generationen då den senast ritades klart
const _ritasNu = new Set();      // flikar som ritas just nu (ritningen får läsa sina egna diagram)

/** Något som styr vad som får visas har ändrats: allt som är ritat hittills är inaktuellt. */
function ritGenerationNy() { _ritGeneration++; }
function ritGeneration() { return _ritGeneration; }
/** Ritades fliken före den senaste ändringen, utan att ha ritats om sedan dess? */
function flikInaktuell(flik) { return _ritadVid.has(flik) && _ritadVid.get(flik) !== _ritGeneration; }

/** Fliken som äger ett element, eller null för det som ligger utanför flikarna (dialoger, sidhuvud). */
function _egFlikFor(el) {
    const panel = el && el.closest ? el.closest('.view-panel') : null;
    if (!panel) return null;
    const id = panel.id.replace(/^view-/, '');
    for (const [flik, paneler] of Object.entries(PANEL_GROUPS)) if (paneler.includes(id)) return flik;
    return id;
}

/**
 * Ser till att fliken som äger elementet är ritad med det som gäller nu. Svarar sant när elementet får läsas:
 * fliken är aktuell (eller ritas just nu) och elementet sitter kvar i sidan. En omritning kan ha ersatt
 * elementet — då är det gamla inte längre i sidan, och svaret är falskt.
 */
function exportSakra(el) {
    if (!el) return false;
    const flik = _egFlikFor(el);
    if (!flik) return el.isConnected !== false;   // utanför flikarna (en dialog) — eller ett element som inte sitter kvar i sidan
    // En flik som aldrig ritats genom navigeringen (eller är inaktuell) ritas i det läge som gäller nu — i exportläget
    // också en flik som ritats direkt av en vy, så att skärmens tal aldrig läses som export (ADR-51).
    if (!_ritasNu.has(flik) && (flikInaktuell(flik) || (iExportLage() && !_ritadVid.has(flik)))) {
        try { renderTabContent(flik); } catch (e) { rapporteraFel(`exportgrinden (${flik})`, e); }
        if (flikInaktuell(flik)) return false;                      // fliken gick inte att rita om: ingenting exporteras ur den
    }
    return el.isConnected !== false;
}

/** Elementet med det id:t, efter att dess flik har säkrats. Null om det saknas eller inte får läsas. */
function exportElement(id) {
    const el = document.getElementById(id);
    if (!el) return null;
    if (!exportSakra(el)) { const ny = document.getElementById(id); return ny && ny !== el && exportSakra(ny) ? ny : null; }
    return document.getElementById(id);
}

/** Ritar om varje flik som har ritats någon gång men inte är aktuell — före en export som tar "allt som är ritat" (ZIP). */
function exportSakraAlla() {
    for (const flik of [..._ritadVid.keys()]) {
        if (!flikInaktuell(flik) || _ritasNu.has(flik)) continue;
        try { renderTabContent(flik); } catch (e) { rapporteraFel(`exportgrinden (${flik})`, e); }
    }
}

/**
 * Tömmer det ritade innehållet i varje flik utom dem i `utom` (den öppna fliken och Översikt, som ritas om direkt).
 * Anropas när tröskeln ändras: en flik som inte syns ska inte bära tal från en tröskel som inte längre gäller —
 * varken i tabeller, i diagrammens figurer eller i flikens topp. Fliken ritas på nytt när den öppnas eller när en
 * export behöver den. Samma behållare som "Rensa all data" tömmer (26-rensning.js); sidans fasta texter rörs inte.
 */
function tomFlikarUtom(utom = new Set()) {
    const ska = el => { const flik = _egFlikFor(el); return !!flik && !utom.has(flik); };
    for (const id of [...RENSA_BEHALLARE, ...RENSA_OVRIGT]) { const el = document.getElementById(id); if (el && ska(el)) el.innerHTML = ''; }
    for (const id of RENSA_TABELLER) { const tb = document.querySelector(`#${id} tbody`); if (tb && ska(tb)) tb.innerHTML = ''; }
    if (typeof _rfBehallare !== 'undefined') for (const el of [..._rfBehallare]) if (!el.isConnected || ska(el)) { rensaFigur(el); el.innerHTML = ''; }
    document.querySelectorAll('.view-panel [id^="chart-"]:not(.chart-export-meny)').forEach(el => { if (ska(el)) el.innerHTML = ''; });
    document.querySelectorAll('.view-panel .slutsatser, .view-panel .urvalsrad:not(#ak-urval)').forEach(el => { if (ska(el)) el.innerHTML = ''; });
    { const t = document.getElementById('ak-urval-text'); if (t && ska(t)) t.textContent = ''; }   // väljaren i samma rad hör till sidan
    document.querySelectorAll('.view-panel .avsnitt-nyckel').forEach(el => { if (ska(el)) { el.textContent = ''; el.classList.remove('ar-kritisk'); } });
    const tryck = document.getElementById('print-report');
    if (tryck) tryck.innerHTML = '';     // en färdig utskrift bär kopior av tabellerna
}
// SPDX-License-Identifier: MIT
// Copyright 2026 Felix Jansson
// ---- Excel-export: alla flikar och JPA-protokollet (EU 2023/970 art. 10) ----
/**
 * Bladen som "Excel (alla flikar)" kommer att innehålla, i ordning — underlaget till exportens förhandsbesked.
 * Listan följer villkoren i _excelAlltBok nedan; ett test håller dem lika.
 */
// Bladlistan räknas som exporten: i exportläget (ADR-51), så att beskedet och arbetsboken får samma blad.
function excelAlltBlad(...a) { return medExportLage(() => _excelAlltBladExport.apply(null, /** @type {any} */ (a))); }
function _excelAlltBladExport() {
    if (!state.data.length) return [];
    const harRef = state.policy.length > 0 || state.statistik.length > 0;
    return ['Löneöversikt', 'Per BAS', ...((state.rapportTabeller || []).length ? ['Egna tabeller'] : []), 'EU-Lonekartlaggning', ...(harRef ? ['Prioritering'] : []), 'Lonegap', 'Konsskevhet', ..._excelDiagramBlad().map(b => b[0]), 'Sektorer',
        ...(state.statistik.length ? ['Jamforelsestatistik'] : []), ...(bedomningUnderlag() ? ['Underlagets kvalitet'] : []), 'Metodik', 'Metod & parametrar'];
}

/** Raderna i bladet Egna tabeller, eller null när inga recept finns. Tal som tal, med kolumnrubriken som enhet. */
function _excelEgnaRader() {
    const recept = state.rapportTabeller || [];
    if (!recept.length || typeof _trTabeller !== 'function') return null;
    const tal = (v, typ) => (v == null || typeof v !== 'number' || !isFinite(v) ? (v == null ? '' : v) : (typ === 'kr' || typ === 'antal' ? Math.round(v) : Math.round(v * 100) / 100));
    const rows = [['Egna tabeller', `byggda i Utforska; minsta gruppstorlek ${kTroskel()}: grupper med färre personer redovisas inte`], []];
    for (const r of recept) {
        const tabeller = _trTabeller(getData(), r, { k: kTroskel() });
        if (!tabeller.length) { rows.push([r.namn, 'ingen grupp når minsta gruppstorlek'], []); continue; }
        for (const t of tabeller) {
            rows.push([t.rubrik, _trBeskrivning(r)]);
            rows.push(t.kolumner.map(c => c.rubrik + (c.typ === 'kr' ? ' (kr/mån)' : c.typ === 'pct1' ? ' (%)' : '')));
            t.rader.forEach(rad => rows.push(rad.map((v, i) => tal(v, t.kolumner[i].typ))));
            if (t.not) rows.push([t.not]);
            rows.push([]);
        }
    }
    return rows;
}

/** Raderna i bladet Per BAS, eller null utan underlag. */
function _excelPerBasRader() {
    const pb = typeof rmPerBasUnderlag === 'function' ? rmPerBasUnderlag(getData(), kTroskel()) : null;
    if (!pb || !pb.intervall.length) return null;
    const tal = v => (v == null || !isFinite(v) ? '' : Math.round(v));
    const pct = v => (v == null || !isFinite(v) ? '' : Math.round(v * 10) / 10);
    const MATT = { p10: 'P10', p25: 'P25', med: 'Median', p75: 'P75', p90: 'P90', medel: 'Medellön' };
    const matt = pb.recept.matt;
    const per = pb.dim === 'sektor' ? 'sektor' : 'BAS-intervall', kort = pb.dim === 'sektor' ? 'Sektor' : 'BAS';
    const rows = [[`Lönestruktur per ${per}`, `minsta gruppstorlek ${pb.k}: grupper med färre personer redovisas inte`], []];
    for (const i of pb.intervall) {
        rows.push([`${kort} ${i.bas}`, `${i.n} anställda, ${i.nKv} kvinnor och ${i.nMa} män, ${i.antalYrken} yrkesgrupper`]);
        rows.push(['Grupp', 'Antal', ...matt.map(m => MATT[m])]);
        i.rader.forEach(r => rows.push([r.namn, r.n == null ? '' : r.n, ...matt.map(m => tal(r[m]))]));
        if (i.utelamnade.length) rows.push([`Redovisas inte (färre än ${pb.k} personer): ${i.utelamnade.join(', ')}`]);
        if (!i.konVisas) rows.push([`Kvinnor och män redovisas inte var för sig: ett kön har färre än ${pb.k} personer`]);
        rows.push([]);
    }
    if (pb.basUtelamnade.length) rows.push([`${pb.dimEtikett} som inte redovisas (färre än ${pb.k} personer): ${pb.basUtelamnade.join(', ')}`], []);
    if (pb.konsgap) {
    rows.push([`Löneskillnader inom likvärdigt arbete, per ${per}`]);
    rows.push(['BAS', 'Antal', 'Medellön alla', 'Medellön män', 'Medellön kvinnor', 'Kvinnors medellön i % av mäns', 'Andel kvinnor (%)', 'Medelålder alla', 'Medelålder män', 'Medelålder kvinnor']);
    pb.konsgap.rader.forEach(r => rows.push([r.bas, r.n, tal(r.medel), tal(r.medelMa), tal(r.medelKv), pct(r.kvot), pct(r.andelKv), tal(r.alder), tal(r.alderMa), tal(r.alderKv)]));
    rows.push([]);
    }
    if (pb.aldersgrupper) {
    rows.push([`Löneskillnader i åldersgrupper, per ${per}`]);
    rows.push(['BAS', 'Antal', 'Medelålder', 'Medellön alla', ...pb.aldersgrupper.grupper.map(g => `Medellön ${g} år`)]);
    pb.aldersgrupper.rader.forEach(r => rows.push([r.bas, r.n, tal(r.alder), tal(r.medel), ...r.perGrupp.map(tal)]));
    }
    return rows;
}

/**
 * Talen bakom flikarnas diagram och översiktstabell, som egna blad: det som står i bilden ska gå att räkna vidare på.
 * Samma funktioner som ritar vyerna lämnar raderna, så bladen följer vyernas regler för minsta gruppstorlek — en
 * grupp som inte ritas får ingen rad. Bladen gäller hela organisationen, också när en flik är avgränsad.
 * Sist bladet Lönepolitik (läget i lönespannet per yrkesgrupp och per kön), när ett ställningstagande är inläst.
 * @returns {[string, any[][]][]} bladets namn och rader
 */
function _excelDiagramBlad() {
    const d = getData(), k = kTroskel(), ut = [], r1 = v => Math.round(v * 10) / 10;
    const bas = _laOversiktRader(d);
    if (bas.length) ut.push(['Lika arbete per BAS', [
        ['Kvinnors och mäns lön per BAS-intervall (översiktstabellen på Lika arbete)'], [],
        ['BAS-intervall', 'Antal kvinnor', 'Antal män', 'Median kvinnor (kr)', 'Median män (kr)', 'Skillnad (kr)', 'Kvinnors median i % av mäns', 'Konfidensintervall 95 %, nedre', 'Konfidensintervall 95 %, övre', 'Status'],
        ...bas.map(o => [o.bas, o.nKv, o.nMa, Math.round(o.medKv), Math.round(o.medMa), Math.round(o.medKv - o.medMa), r1(o.gap), o.ci ? r1(o.ci.lo) : '', o.ci ? r1(o.ci.hi) : '', _laOversiktStatus(o).serie])]]);
    const tratt = _laTrattUnderlag(d);
    if (tratt) ut.push(['Slumpens granser', [
        ['Yrkesgrupperna mot slumpens gränser (trattdiagrammet på Lika arbete)'],
        [`Yrkesgrupper där både kvinnor och män är minst ${k}. Gränserna är de 95-procentiga för gruppens storlek.`], [],
        ['Yrkesgrupp', 'BAS-intervall', 'Antal kvinnor', 'Antal män', 'Kvinnors median i % av mäns', 'Gräns, nedre', 'Gräns, övre', 'Bedömning'],
        ...tratt.punkter.map(p => [p.yrke, p.bas, p.nKv, p.nMa, r1(p.kvot), r1(p.gransLag), r1(p.gransHog), p.utanfor ? 'Utanför gränserna' : 'Inom gränserna'])]]);
    const arKv = r => typeof r.kon === 'string' && r.kon.includes('kvinna'), arMa = r => r.kon === 'man' || r.kon === 'män';
    const alder = _konAlderGapRader(d.filter(arKv), d.filter(arMa), k);
    if (alder.visade.length) ut.push(['Lonegap per alder', [
        ['Lönegap per åldersgrupp (Ålder & karriär)'],
        ...(alder.dolda.length ? [[`Visas inte, ett kön har färre än ${k} personer: ${alder.dolda.join(', ')}.`]] : []), [],
        ['Åldersgrupp', 'Antal kvinnor', 'Antal män', 'Median kvinnor (kr)', 'Median män (kr)', 'Kvinnors median i % av mäns', 'Konfidensintervall 95 %, nedre', 'Konfidensintervall 95 %, övre'],
        ...alder.visade.map(a => [a.namn, a.nKv, a.nMa, Math.round(a.medKv), Math.round(a.medMa), r1(a.gap), a.ci ? r1(a.ci.lo) : '', a.ci ? r1(a.ci.hi) : ''])]]);
    // Lönepolitik: bara när ett ställningstagande är inläst och matchar underlaget (75-lonepolitik.js).
    const lp = typeof _lpExcelBlad === 'function' ? _lpExcelBlad() : null;
    if (lp) ut.push(['Lönepolitik', lp]);
    return ut;
}

/** Metodraden för bladet Lönepolitik, när det finns i arbetsboken. */
function _excelLonepolitikMetod(blad) {
    if (!blad.some(b => b[0] === 'Lönepolitik')) return [];
    return [['Bladet Lönepolitik', `Läget i referensens lönespann (0 % = P10, 100 % = P90) per yrkesgrupp, per kön och BAS-intervall samt fördelningen i spannets tredjedelar per kön och efterlevnaden per BAS-intervall — samma mått och samma regler för minsta gruppstorlek som fliken Lönepolitik: yrkesgrupper under ${kTroskel()} personer utan lönemått, könsuppdelade mått bara där varje kön har minst ${kTroskel()} personer.`]];
}

// Går alltid genom exportläget (ADR-51): djupräknaren håller skärmen i exportläget tills den sista pågående exporten är klar.
function exportAllToExcel(...a) { return medExportLage(() => _exportAllToExcelExport.apply(null, /** @type {any} */ (a))); }
function _exportAllToExcelExport() {
    if (!state.data.length) { alert('Ladda upp data först.'); return; }
    if (typeof XLSX === 'undefined') { alert('XLSX-bibliotek saknas.'); return; }
    const wb = _excelAlltBok();
    XLSX.writeFile(wb, `lonekartlaggning_komplett_${new Date().toISOString().slice(0,10)}.xlsx`);
    _showExportSensitivityToast();
}

/** Bygger arbetsboken för "Excel (alla flikar)". */
// Går alltid genom exportläget (ADR-51): djupräknaren håller skärmen i exportläget tills den sista pågående exporten är klar.
function _excelAlltBok(...a) { return medExportLage(() => __excelAlltBokExport.apply(null, /** @type {any} */ (a))); }
function __excelAlltBokExport() {

    // Self-healing: säkerställ att flik-tabellerna är renderade innan de läses.
    // Täcker både den deferrade inläsningen (skevhet/kon körs strax efter load)
    // och flikar som aldrig besökts (EU-matrisen renderades annars först vid
    // flikbesök → arket föll tyst bort ur exporten).
    const ensure = (sel, fn) => { if (!document.querySelector(sel)) { try { fn(); } catch (_e) { /* tolerant */ } } };
    ensure('#rapport-table tbody tr', generateRapport);
    ensure('#skevhet-table tbody tr', generateSkevhet);
    ensure('#matrix-table tbody tr', generateEUDirectiveMatrix);
    if (state.policy.length || state.statistik.length) ensure('#prio-table tbody tr', renderPrioritering);
    if (state.statistik.length) ensure('#benchmark-table tbody tr', generateBenchmark);

    const wb = XLSX.utils.book_new();
    const tableToSheet = (id, fallback) => {
        const sheet = tableToCleanSheet(id);
        if (sheet) return sheet;
        return fallback ? XLSX.utils.aoa_to_sheet(fallback) : null;
    };

    // Bladet Löneöversikt
    const rapportSheet = tableToSheet('rapport-table');
    if (rapportSheet) XLSX.utils.book_append_sheet(wb, rapportSheet, 'Löneöversikt');

    // Bladet Per BAS: tabellerna i den form en skriven lönekartläggning brukar ha (samma underlag som Word-utkastets
    // avsnitt Lönestruktur per BAS-intervall; tröskeln tillämpas i src/lib/perbas.js).
    const perBasRader = _excelPerBasRader();
    if (perBasRader) XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(perBasRader), 'Per BAS');
    // Bladet Egna tabeller (ADR-52): recepten ur Utforska, räknade med tröskeln.
    const egnaRader = _excelEgnaRader();
    if (egnaRader) XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(egnaRader), 'Egna tabeller');

    // Sheet: EU-Lönekartläggning
    const matrixSheet = tableToSheet('matrix-table');
    if (matrixSheet) XLSX.utils.book_append_sheet(wb, matrixSheet, 'EU-Lonekartlaggning');

    // Sheet: Prioritering
    const prioSheet = tableToSheet('prio-table');
    if (prioSheet) XLSX.utils.book_append_sheet(wb, prioSheet, 'Prioritering');

    // Sheet: Lönegap & Könsfördelning
    const paygapSheet = tableToSheet('paygap-table');
    if (paygapSheet) XLSX.utils.book_append_sheet(wb, paygapSheet, 'Lonegap');
    const skevhetSheet = tableToSheet('skevhet-table');
    if (skevhetSheet) XLSX.utils.book_append_sheet(wb, skevhetSheet, 'Konsskevhet');
    const diagramBlad = _excelDiagramBlad();
    for (const [namn, rader] of diagramBlad) XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(rader), namn);

    // Sheet: Sektorer (AID-huvudområden, ADR-33) — samma k-regler som vyn.
    ensure('#sektor-table tbody tr', () => renderSektorer(getData()));
    const sektorSheet = tableToSheet('sektor-table');
    if (sektorSheet) XLSX.utils.book_append_sheet(wb, sektorSheet, 'Sektorer');

    // Sheet: Benchmark mot jämförelsestatistiken
    // Bara med inläst jämförelsestatistik: samma villkor som förhandsbeskedet (excelAlltBlad), oberoende av vilka flikar som visats.
    const bmSheet = state.statistik.length ? tableToSheet('benchmark-table') : null;
    if (bmSheet) {
        // Tabellen följer flikens filter; säg det i bladet (ADR-35).
        if (jamforelseUrvalText()) XLSX.utils.sheet_add_aoa(bmSheet, [[], [jamforelseUrvalText()]], { origin: -1 });
        XLSX.utils.book_append_sheet(wb, bmSheet, 'Jamforelsestatistik');
    }

    // Sheet: Underlagets kvalitet (ADR-19)
    const uk = bedomningUnderlag();
    if (uk) {
        const ukRows = [
            ['Underlagets kvalitet', UK_ETIKETT[uk.status]],
            [],
            ['Kriterium', 'Status', 'Värde', 'Förklaring']
        ];
        uk.kriterier.forEach(c => ukRows.push([c.namn, UK_ETIKETT[c.status], (typeof c.varde === 'number') ? Math.round(c.varde * 10) / 10 : (c.varde ?? ''), c.text]));
        XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(ukRows), 'Underlagets kvalitet');
    }

    // Sheet: Metodik & urval (audit)
    const metRows = [
        ['Metodik & urval — kvalitetssäkring'],
        ['Genererad', new Date().toLocaleString('sv-SE')],
        []
    ];
    Object.entries(auditRegistry).forEach(([id, a]) => {
        metRows.push([a.title || id]);
        metRows.push(['Total i datafilen', a.totalRaw]);
        [...(a.parseExcl||[]), ...(a.analysisExclusions||[])].forEach(([r,c]) => {
            metRows.push(['− ' + r.replace(/<[^>]+>/g, ''), c]);
        });
        const used = a.usedInAnalysis !== undefined ? a.usedInAnalysis : a.afterFilter;
        metRows.push(['= Använda i analysen', used]);
        metRows.push([]);
        if (a.formler && a.formler.length) {
            metRows.push(['Formler & definitioner']);
            a.formler.forEach(([n, dsc]) => metRows.push(['  ' + n, dsc.replace(/<[^>]+>/g, '')]));
            metRows.push([]);
        }
        if (a.notes && a.notes.length) {
            metRows.push(['Speciella regler']);
            a.notes.forEach(n => metRows.push(['  ' + n.replace(/<[^>]+>/g, '')]));
            metRows.push([]);
        }
    });
    XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(metRows), 'Metodik');

    _appendMethodSheet(wb, { extra: _excelLonepolitikMetod(diagramBlad) });
    return wb;
}

// ---- Joint Pay Assessment-protokoll (EU 2023/970 Art. 10) ----
/**
 * Etiketterna för de två "exkluderade p.g.a. k-anonymitet"-raderna. Yrkesgrupperna
 * prövas mot redovisningströskeln (kTroskel()); BAS-regressionen avgörs av
 * statGolv() (se _computePerBasGap), så dess rad nämner golvet.
 */
function _jpaExkluderadeTexter() {
    return {
        yrken: `  Exkluderade p.g.a. k-anonymitet (n<${kTroskel()} per kön)`,
        bas: `  Exkluderade p.g.a. k-anonymitet (n<${statGolv()} per kön)`
    };
}
/**
 * Genererar en samrådsprotokoll-Excel speciellt utformad för facklig samverkan.
 *
 * Strikt EU 2023/970 Art. 10-process:
 *   - Listar enbart grupper med oförklarat gap > 5% (utredningskrav)
 *   - K-anonymitet appliceras: grupper med färre än kTroskel() personer av något kön exkluderas helt
 *   - Tomma protokoll-fält för sakliga skäl, fackliga kommentar, åtgärder
 *   - Signaturblad för arbetsgivare + fackliga representanter
 *   - Transparens om vad som EXKLUDERATS p.g.a. k-anonymitet (antal, ingen PII)
 *
 * Output: lonekartlaggning_JPA_protokoll_YYYY-MM-DD.xlsx
 */
// Går alltid genom exportläget (ADR-51): djupräknaren håller skärmen i exportläget tills den sista pågående exporten är klar.
function exportJPAProtocol(...a) { return medExportLage(() => _exportJPAProtocolExport.apply(null, /** @type {any} */ (a))); }
function _exportJPAProtocolExport() {
    if (!state.data.length) { alert('Ladda upp data först.'); return; }
    if (typeof XLSX === 'undefined') { alert('XLSX-bibliotek saknas.'); return; }

    const d = getData();
    const now = new Date();
    const isoDate = now.toISOString().slice(0, 10);
    const localDate = now.toLocaleDateString('sv-SE');
    const profileLabel = state.profile.benchmarkLabel;

    // § 3:10-paren beräknas EN GÅNG här, så att försättssidan och flik 3b
    // alltid är konsistenta.
    const lvResult = typeof computeLikvardighetPairs === 'function'
        ? computeLikvardighetPairs()
        : null;
    // Synka cachen så ev. efterföljande tabb-render visar samma siffror.
    if (state.likvardighet) state.likvardighet.result = lvResult;
    // k-anonymitet: protokollet redovisar bara par där båda grupperna når tröskeln (undantaget gäller
    // bara fliken Likvärdigt arbete); antalet som utelämnats anges i stället.
    const lvRedovisning = _parForRedovisning(lvResult?.pairs);
    const lvPairsCount = lvRedovisning.par.length;

    // ---- A) Identifiera JPA-grupper (lika arbete = yrkesgrupp) ----
    // Median-jämförelse + k-anonymitet
    const yrkeGroups = {};
    d.forEach(r => {
        if (!yrkeGroups[r.yrke]) yrkeGroups[r.yrke] = { kv: [], ma: [] };
        if (r.kon.includes('kvinna'))               yrkeGroups[r.yrke].kv.push(r);
        else if (r.kon === 'man' || r.kon === 'män') yrkeGroups[r.yrke].ma.push(r);
    });
    const jpaYrken = [];
    let yrkenExkluderadeMaskerade = 0;
    let yrkenExkluderadeOjamn = 0;
    Object.entries(yrkeGroups).forEach(([yrke, g]) => {
        if (g.kv.length === 0 && g.ma.length === 0) return;  // tom
        if (g.kv.length < kTroskel() || g.ma.length < kTroskel()) {
            yrkenExkluderadeMaskerade++;
            return;
        }
        const medKv = Stat.median(g.kv.map(r => r.lon));
        const medMa = Stat.median(g.ma.map(r => r.lon));
        if (medMa <= 0) return;
        const gapPct = (medKv / medMa - 1) * 100;  // negativ = kvinnor lägre
        if (Math.abs(gapPct) <= 5) { yrkenExkluderadeOjamn++; return; }
        jpaYrken.push({
            yrke, nKv: g.kv.length, nMa: g.ma.length, tot: g.kv.length + g.ma.length,
            medKv: Math.round(medKv), medMa: Math.round(medMa),
            gapPct: +gapPct.toFixed(2),
            diffKr: Math.round(medKv - medMa)
        });
    });
    jpaYrken.sort((a, b) => a.gapPct - b.gapPct);  // mest negativa (mest kritiska) först

    // ---- B) Identifiera JPA-grupper (likvärdigt arbete = BAS-intervall) ----
    // OLS-regression per BAS, kräver minst statGolv() av varje kön
    const basList = [...new Set(d.map(r => r.bas))].sort();
    const perBas = _computePerBasGap(d, basList);
    let basExkluderadeMaskerade = 0;
    let basExkluderadeSingular = 0;
    let basExkluderadeUnderTröskel = 0;
    const jpaBas = [];
    perBas.forEach(b => {
        if (b.status === 'too_few')    { basExkluderadeMaskerade++; return; }
        if (b.status === 'singular')   { basExkluderadeSingular++; return; }
        if (Math.abs(b.gapPct) <= 5)   { basExkluderadeUnderTröskel++; return; }
        jpaBas.push(b);
    });
    jpaBas.sort((a, b) => a.gapPct - b.gapPct);

    // ---- C) Bygg arbetsbok ----
    const wb = XLSX.utils.book_new();

    // === Sheet 1: Försättssida + samrådsinformation ===
    const coverRows = [
        ['GEMENSAM LÖNEBEDÖMNING — SAMVERKANSPROTOKOLL', ''],
        ['Direktiv (EU) 2023/970 om lönetransparens, gemensam lönebedömning', ''],
        ['Diskrimineringslagen 3 kap. (lönekartläggning)', ''],
        ['', ''],
        ['Genererad', localDate + ' ' + now.toLocaleTimeString('sv-SE')],
        ['Verktyg', `Öppen lönekartläggning (v${APP_VERSION})`],
        ['Aktiv profil', state.profile.name],
        ['Jämförelseinstitution', profileLabel],
        ['', ''],
        ['— OMFATTNING —', ''],
        ['Totalt antal personer i underlaget', d.length],
        ['Antal yrkesgrupper där kvinnors och mäns median skiljer sig mer än 5 % (lika arbete)', jpaYrken.length],
        ['Antal BAS-intervall med >5% oförklarat gap (likvärdigt arbete)', jpaBas.length],
        [`Antal ${lvRedovisning.not ? 'redovisade ' : ''}kandidatpar i likvärdigt arbete (kvinnodominerat yrke mot icke-kvinnodominerat yrke med lika eller lägre krav)`, lvPairsCount],
        ...(lvRedovisning.not ? [['  Utelämnade kandidatpar', lvRedovisning.not]] : []),
        ['', ''],
        ['— DELTAGARE I SAMRÅDET —', '(fylls i av parterna)'],
        ['Datum för samråd', ''],
        ['Plats / form', ''],
        ['Arbetsgivarens representant 1 (namn)', ''],
        ['Arbetsgivarens representant 1 (befattning)', ''],
        ['Arbetsgivarens representant 2 (namn)', ''],
        ['Arbetsgivarens representant 2 (befattning)', ''],
        ['Facklig representant 1 (namn)', ''],
        ['Facklig representant 1 (organisation)', ''],
        ['Facklig representant 2 (namn)', ''],
        ['Facklig representant 2 (organisation)', ''],
        ['Facklig representant 3 (namn)', ''],
        ['Facklig representant 3 (organisation)', ''],
        ['Övriga närvarande', ''],
        ['', ''],
        ['— GEMENSAM SAMMANFATTNING —', '(fylls i efter samrådet)'],
        ['Huvudsakliga slutsatser', ''],
        ['Övergripande åtgärdsplan', ''],
        ['Tidplan för åtgärder', ''],
        ['Nästa uppföljning (datum)', ''],
        ['', ''],
        ['Detta protokoll ska bifogas arbetsgivarens lönekartläggning för året.', ''],
        ['Originalexemplar förvaras i låst arkiv enligt arbetsgivarens dokumenthanteringsplan.', '']
    ];
    const coverSheet = XLSX.utils.aoa_to_sheet(coverRows);
    coverSheet['!cols'] = [{ wch: 50 }, { wch: 60 }];
    coverSheet['!merges'] = [
        { s: { r: 0, c: 0 }, e: { r: 0, c: 1 } },
        { s: { r: 1, c: 0 }, e: { r: 1, c: 1 } },
        { s: { r: 2, c: 0 }, e: { r: 2, c: 1 } }
    ];
    XLSX.utils.book_append_sheet(wb, coverSheet, '1. Försättssida');

    // === Sheet 2: Yrkesgrupper med >5% gap (lika arbete) ===
    const yrkenHeaderRow = [
        'Nr', 'AID / Yrkesgrupp', 'N totalt', 'N kvinnor', 'N män',
        'Median kvinnor (kr)', 'Median män (kr)', 'Differens (kr)', 'Kvinnors median i % av mäns',
        // Tomma protokollfält
        'Sakliga skäl — arbetsgivarens analys',
        'Fackliga partens kommentar / motargument',
        'Status efter samråd (motiverat / behöver åtgärd / oklart)',
        'Överenskommen åtgärd',
        'Tidplan',
        'Ansvarig'
    ];
    const yrkenRows = [yrkenHeaderRow];
    if (jpaYrken.length === 0) {
        yrkenRows.push(['—', 'Inga yrkesgrupper där kvinnors och mäns median skiljer sig mer än 5 %, efter k-anonymitet', '', '', '', '', '', '', '', '', '', '', '', '', '']);
    } else {
        jpaYrken.forEach((j, idx) => {
            yrkenRows.push([
                idx + 1, j.yrke, j.tot, j.nKv, j.nMa,
                j.medKv, j.medMa, j.diffKr, typeof j.gapPct === 'number' ? +(100 + j.gapPct).toFixed(1) : j.gapPct,
                '', '', '', '', '', ''  // protokoll-celler tomma
            ]);
        });
    }
    const yrkenSheet = XLSX.utils.aoa_to_sheet(yrkenRows);
    yrkenSheet['!cols'] = [
        { wch: 4 }, { wch: 42 }, { wch: 10 }, { wch: 10 }, { wch: 10 },
        { wch: 16 }, { wch: 16 }, { wch: 14 }, { wch: 12 },
        { wch: 50 }, { wch: 50 }, { wch: 32 }, { wch: 40 }, { wch: 18 }, { wch: 22 }
    ];
    yrkenSheet['!freeze'] = { xSplit: 2, ySplit: 1 };
    _applyColumnNumFormats(yrkenSheet, SV_NUM_FORMATS);
    XLSX.utils.book_append_sheet(wb, yrkenSheet, '2. Lika arbete (yrken)');

    // === Sheet 3: BAS-intervall med >5% oförklarat gap (likvärdigt arbete) ===
    const basHeaderRow = [
        'Nr', 'BAS-intervall', 'N totalt', 'N kvinnor', 'N män',
        'Oförklarat gap (%)', '95% KI lägre', '95% KI övre',
        'p-värde', 'R² för modellen', 'Statistiskt säkerställd',
        // Protokoll-fält
        'Sakliga skäl — arbetsgivarens analys',
        'Fackliga partens kommentar',
        'Status efter samråd',
        'Överenskommen åtgärd',
        'Tidplan',
        'Ansvarig'
    ];
    const basRows = [basHeaderRow];
    if (jpaBas.length === 0) {
        basRows.push(['—', 'Inga BAS-intervall med oförklarat gap >5% efter k-anonymitet', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '']);
    } else {
        jpaBas.forEach((b, idx) => {
            basRows.push([
                idx + 1, b.bas, b.n, b.kvN, b.maN,
                +b.gapPct.toFixed(2), +b.ciLow.toFixed(2), +b.ciHigh.toFixed(2),
                b.pValue < 0.001 ? '< 0.001' : +b.pValue.toFixed(4),
                +(b.R2 * 100).toFixed(1) + '%',
                b.pValue < 0.05 ? 'Ja' : 'Nej',
                '', '', '', '', '', ''
            ]);
        });
    }
    const basSheet = XLSX.utils.aoa_to_sheet(basRows);
    basSheet['!cols'] = [
        { wch: 4 }, { wch: 14 }, { wch: 10 }, { wch: 10 }, { wch: 10 },
        { wch: 14 }, { wch: 12 }, { wch: 12 }, { wch: 12 }, { wch: 12 }, { wch: 14 },
        { wch: 50 }, { wch: 50 }, { wch: 32 }, { wch: 40 }, { wch: 18 }, { wch: 22 }
    ];
    basSheet['!freeze'] = { xSplit: 2, ySplit: 1 };
    _applyColumnNumFormats(basSheet, SV_NUM_FORMATS);
    XLSX.utils.book_append_sheet(wb, basSheet, '3. Likvärdigt arbete (BAS)');

    // === Sheet 3b: § 3:10 Likvärdighet (kv-dom yrken vs icke-kv-dom yrken) ===
    // Använder lvResult som beräknats högst upp i
    // funktionen — så försättssidans räknare och tabellen i flik 3b alltid
    // är från samma compute.
    if (lvResult && lvResult.pairs.length && !lvRedovisning.par.length) {
        // Alla par har en grupp under tröskeln: arket anger det i stället för att tiga eller påstå att par saknas.
        XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet([[lvRedovisning.not]]), '3b. § 3-10 Likvärdighet');
    }
    if (lvRedovisning.par.length) {
        // Inom-organisationen-jämförelse primär, jämförelsestatistiken
        // som extern fallback per BAS. Bootstrap-CI på varje par.
        const lvSig = ci => !ci ? 'CI ej beräknad' : (ci.lo > 0 ? 'Säker (CI > 0)' : 'Slump? (CI överlappar 0)');
        const lvKälla = p => p.jamforKalla === 'intern' ? 'Intern (organisation)'
            : (p.maKlassKort === 'lokal' ? 'jämförelsestatistiken' : 'SKR:s personalstatistik');
        const lvHeader = [
            'Nr',
            'Org. AID', 'Org. Yrke', 'BAS', 'Org. n', 'Org. % kvinnor', 'Median Org. (kr)',
            'Jämf. AID', 'Jämf. Yrke', 'Jämf. % kvinnor', 'Jämf. n', 'Jämförelsekälla', 'Median Jämf. (kr)',
            'Gap (kr)', 'Gap (%)', '95 % KI lägre (kr)', '95 % KI övre (kr)', 'Säkerhet', 'Påverkansindex',
            'Sakliga skäl — arbetsgivarens analys',
            'Fackliga partens kommentar',
            'Status efter samråd',
            'Överenskommen åtgärd',
            'Tidplan',
            'Ansvarig'
        ];
        const lvRows = [lvHeader];
        lvRedovisning.par.forEach((p, i) => lvRows.push([
            i + 1,
            p.kvAid, p.kvLabel, p.kvBas, p.kvN, +p.kvKvinnoPct.toFixed(1), Math.round(p.kvMedian),
            p.maAid, p.maLabel, +p.maKvAndel.toFixed(1), p.maN != null ? p.maN : '—', lvKälla(p), Math.round(p.maMedian),
            Math.round(p.gapKr), +p.gapPct.toFixed(2),
            p.gapCI ? Math.round(p.gapCI.lo) : '—',
            p.gapCI ? Math.round(p.gapCI.hi) : '—',
            lvSig(p.gapCI),
            Math.round(p.allvarsindex),
            '', '', '', '', '', ''
        ]));
        if (lvRedovisning.not) lvRows.push([], [lvRedovisning.not]);
        const lvSheet = XLSX.utils.aoa_to_sheet(lvRows);
        lvSheet['!cols'] = [
            { wch: 4 }, { wch: 8 }, { wch: 28 }, { wch: 6 }, { wch: 7 }, { wch: 12 }, { wch: 14 },
            { wch: 8 }, { wch: 28 }, { wch: 12 }, { wch: 7 }, { wch: 20 }, { wch: 14 },
            { wch: 11 }, { wch: 8 }, { wch: 13 }, { wch: 13 }, { wch: 24 }, { wch: 14 },
            { wch: 50 }, { wch: 50 }, { wch: 28 }, { wch: 40 }, { wch: 18 }, { wch: 22 }
        ];
        lvSheet['!freeze'] = { xSplit: 3, ySplit: 1 };
        _applyColumnNumFormats(lvSheet, SV_NUM_FORMATS);
        // OBS: kolon är förbjudet i Excel-arknamn (SheetJS kastar) — därav "3-10".
        // Demodata saknar § 3:10-par, så arket prövas bara med riktiga par.
        XLSX.utils.book_append_sheet(wb, lvSheet, '3b. § 3-10 Likvärdighet');
    }

    // === Sheet 4: Exkluderade grupper (transparens om k-anonymitet) ===
    const excludedRows = [
        ['EXKLUDERADE GRUPPER — transparens för fackliga parter', ''],
        ['', ''],
        ['Inga personidentifierande uppgifter visas. Endast antal exkluderade grupper.', ''],
        ['', ''],
        ['Lika arbete (yrkesgrupper):', ''],
        [_jpaExkluderadeTexter().yrken, yrkenExkluderadeMaskerade],
        ['  Under 5%-tröskeln (rågap ≥ 5%)', yrkenExkluderadeOjamn],
        ['', ''],
        ['Likvärdigt arbete (BAS-intervall):', ''],
        [_jpaExkluderadeTexter().bas, basExkluderadeMaskerade],
        ['  Exkluderade p.g.a. singulär regression (multikollinearitet)', basExkluderadeSingular],
        ['  Under 5%-tröskeln (oförklarat gap ≥ 5%)', basExkluderadeUnderTröskel],
        ['', ''],
        ['Gränsen 5 % kommer från direktivets regler om gemensam lönebedömning (art. 10).', ''],
        [`k-anonymitet (n<${kTroskel()}) skyddar enskilda anställdas integritet (uppgiftsminimering och inbyggt dataskydd enligt dataskyddsförordningen).`, ''],
        ['Grupper under k-tröskeln kan inte analyseras säkert utan risk för återidentifiering.', ''],
        ['Om dessa grupper behöver granskas separat bör det ske utan numeriska bilagor.', '']
    ];
    const excludedSheet = XLSX.utils.aoa_to_sheet(excludedRows);
    excludedSheet['!cols'] = [{ wch: 60 }, { wch: 16 }];
    XLSX.utils.book_append_sheet(wb, excludedSheet, '4. Exkluderat (k-anon)');

    // === Sheet 5: Metodik & rättslig grund ===
    const metodikRows = [
        ['METODIK & RÄTTSLIG GRUND', ''],
        ['', ''],
        ['— Rättslig grund —', ''],
        ['Direktiv (EU) 2023/970, art. 10', 'Gemensam lönebedömning krävs hos arbetsgivare som lönerapporterar när skillnaden i någon kategori arbetstagare är 5 % eller mer, inte motiveras av objektiva könsneutrala kriterier och inte åtgärdats inom sex månader.'],
        ['Direktiv (EU) 2023/970, art. 10', 'Bedömningen görs tillsammans med arbetstagarrepresentanterna; åtgärder inom rimlig tid.'],
        ['Diskrimineringslagen, lönekartläggning', 'Löneskillnad ska kunna motiveras med sakliga skäl: arbetets svårighet, ansvar, krav på utbildning/erfarenhet eller andra särskilda omständigheter.'],
        ['Diskrimineringslagen, likvärdigt arbete', 'Likvärdigt arbete bedöms genom analys av krav som arbetet ställer (utbildning, ansvar, ansträngning, arbetsförhållanden).'],
        ['Diskrimineringslagen, kvinnodominerat arbete', 'Arbetsgivaren ska analysera om kvinnodominerade yrken har lägre lön än icke-kvinnodominerade yrken med likvärdiga eller lägre krav i arbetet. BAS-rank används i flik 3b som ordinal proxy för arbetskrav — slutgiltig kravvärdering kräver kvalitativ granskning.'],
        ['Diskrimineringslagen 3:11', 'Konstaterade osakliga löneskillnader ska åtgärdas så snart som möjligt, senast inom 3 år.'],
        ['', ''],
        ['— Statistisk metodik —', ''],
        ['Lika arbete (yrkesgrupp)', 'Direkt median-jämförelse mellan kvinnors och mäns löner inom samma AID-kod. Kvinnors median i procent av mäns = median_kv / median_mä × 100; under 100 betyder att kvinnor ligger lägre.'],
        ['Likvärdigt arbete (BAS-intervall)', 'OLS-regression: log(lön) ~ kön + ålder (centrerad) inom varje BAS. Oförklarat gap = kön-koefficient omräknad till procentskillnad. HC3-robusta standardfel (Long & Ervin 2000).'],
        ['Konfidensintervall', '95% KI = β ± t(0,975; n−k) × HC3 robust SE, transformerat tillbaka från log-skala; t-kvantilen är 1,96 vid n−k ≥ 100 och större vid färre frihetsgrader.'],
        ['Statistisk signifikans', 'p < 0.05 = ej slumpmässig skillnad. Tröskel följer Medlingsinstitutets praxis.'],
        ['', ''],
        ['— k-anonymitet —', ''],
        ['Tröskel', `n ≥ ${kTroskel()} per kön krävs för att en grupp ska redovisas individuellt.`],
        ['Bakgrund', 'Skydd mot återidentifiering av enskilda anställda via deduktion (kön + ålder + yrke + BAS).'],
        ['Konsekvens', 'Små grupper exkluderas helt från detta protokoll. Antal exkluderade redovisas i flik 4.'],
        ['', ''],
        ['— Begränsningar att vara medvetna om —', ''],
        ['Sakliga skäl', 'Verktyget identifierar löneskillnader men avgör inte vad som är saklig grund. Den bedömningen är gemensamma parters ansvar.'],
        ['Modellantaganden', 'OLS antar linjär samband mellan ålder och log(lön). Lifecycle-analysen (i verktygets EU-flik) testar detta antagande med kvadratisk åldersterm.'],
        ['Multipel jämförelse', 'Många p-värden testas samtidigt. Vid stort antal BAS-intervall förväntas 1 falskt positivt resultat per 20 tester av slump. Tolka p-värden i kontext.']
    ];
    const metodikSheet = XLSX.utils.aoa_to_sheet(metodikRows);
    metodikSheet['!cols'] = [{ wch: 32 }, { wch: 90 }];
    XLSX.utils.book_append_sheet(wb, metodikSheet, '5. Metodik & rättslig grund');

    // === Sheet 6: Signaturblad ===
    const signRows = [
        ['SIGNATURER — GEMENSAM LÖNEBEDÖMNING', ''],
        ['', ''],
        ['Parterna intygar att de tagit del av detta protokoll och dess slutsatser.', ''],
        ['', ''],
        ['— Arbetsgivarrepresentant 1 —', ''],
        ['Namn', ''],
        ['Befattning', ''],
        ['Signatur', ''],
        ['Datum', ''],
        ['', ''],
        ['— Arbetsgivarrepresentant 2 —', ''],
        ['Namn', ''],
        ['Befattning', ''],
        ['Signatur', ''],
        ['Datum', ''],
        ['', ''],
        ['— Facklig representant 1 —', ''],
        ['Namn', ''],
        ['Organisation', ''],
        ['Signatur', ''],
        ['Datum', ''],
        ['', ''],
        ['— Facklig representant 2 —', ''],
        ['Namn', ''],
        ['Organisation', ''],
        ['Signatur', ''],
        ['Datum', ''],
        ['', ''],
        ['— Facklig representant 3 —', ''],
        ['Namn', ''],
        ['Organisation', ''],
        ['Signatur', ''],
        ['Datum', ''],
        ['', ''],
        ['Originalet förvaras hos arbetsgivaren. Kopior till samtliga underskrivande parter.', '']
    ];
    const signSheet = XLSX.utils.aoa_to_sheet(signRows);
    signSheet['!cols'] = [{ wch: 32 }, { wch: 60 }];
    XLSX.utils.book_append_sheet(wb, signSheet, '6. Signaturer');

    // === Spara filen ===
    const filename = `lonekartlaggning_protokoll_gemensam_lonebedomning_${isoDate}.xlsx`;
    _appendMethodSheet(wb);
    XLSX.writeFile(wb, filename);
    _showExportSensitivityToast();
    announceToScreenReader(`Protokoll för gemensam lönebedömning exporterat: ${jpaYrken.length} yrkesgrupp${jpaYrken.length === 1 ? '' : 'er'} och ${jpaBas.length} BAS-intervall över 5%-tröskeln.`);
}

